/// Pinned headroom-ai version. Upgrade logic is disabled; this exact version
/// will be installed if the currently-installed version differs.
///
/// 0.20.x–0.24.x upstream shipped a maturin/Rust-native wheel that was both
/// per-Python-version and per-platform (e.g. `cp312-cp312-macosx_11_0_arm64`,
/// upstream #355). Starting with 0.25.0 the native module is built against the
/// CPython stable ABI (abi3, upstream #516), so a single `cp310-abi3` wheel per
/// platform now covers every CPython >= 3.10 — the pin below
/// (`cp310-abi3-macosx_11_0_arm64`) installs cleanly on our bundled cp312 and
/// stays valid if `PYTHON_STANDALONE_RELEASE` later moves to 3.13+. Only the
/// per-platform axis still matters, which `headroom_wheel_artifact` handles —
/// when bumping this pin, re-pick every platform's wheel URL/sha256 from
/// https://pypi.org/pypi/headroom-ai/<version>/json.
pub(crate) const HEADROOM_PINNED_VERSION: &str = "0.41.0";
const HEADROOM_SMOKE_TEST_TIMEOUT: Duration = Duration::from_secs(15);

/// Kill the RUST-9F onnxruntime import probe after this long: a native
/// DLL-init DEADLOCK (as opposed to the usual crash) must read as "timed
/// out", not hang the already-failing startup path the probe reports on.
const ONNX_PROBE_TIMEOUT: Duration = Duration::from_secs(15);
/// markitdown's `--help` cold-imports a much heavier converter stack
/// (onnxruntime, magika, pdfminer, …) than the core `import headroom`. On
/// macOS 26 the first run of freshly-installed *unsigned* wheel binaries is
/// scanned by Gatekeeper/EDR, which routinely pushes that first import past
/// 15s and trips the smoke-test SIGKILL (RUST-22). It is warn-only, so a too
/// tight bound just produces Sentry noise and false "addon broken" signals.
const MARKITDOWN_SMOKE_TEST_TIMEOUT: Duration = Duration::from_secs(60);
/// Upper bound on the one-time `learn --verbosity` baseline seed run before
/// proxy start. Typical runs are a few seconds (a ~100MB transcript project
/// seeds in ~3s); the cap only trips on pathological corpora, after which the
/// proxy starts anyway and seeding retries next launch.
const HEADROOM_BASELINE_SEED_TIMEOUT: Duration = Duration::from_secs(30);
/// Largest transcript corpus the seed run is pointed at. `learn --verbosity`
/// reads it three times (~2.2s per 100MB on Apple Silicon, 2-3x that on slower
/// disks and CPUs), so a heavy user's busiest project (1GB+) always hit the
/// timeout above, seeded nothing, and retried on every launch, holding proxy
/// start back 30s each time. The busiest project under this cap seeds instead.
// ponytail: fixed cap; if outlier machines still time out, stamp the failed
// size beside the ledger and halve the cap from it on the next launch.
const HEADROOM_BASELINE_SEED_MAX_BYTES: u64 = 400 * 1024 * 1024;
/// Index of pre-built wheels for sdist-only PyPI packages (e.g. hnswlib).
/// GitHub's expanded_assets endpoint serves HTML anchors pip can consume via --find-links.
const VENDOR_WHEELS_INDEX_URL: &str =
    "https://github.com/gglucass/headroom-desktop/releases/expanded_assets/vendor-wheels-v1";
/// Never let pip build a dependency from source. A user's machine is not
/// guaranteed to have Xcode Command Line Tools (nor the Rust toolchain
/// pydantic-core's sdist needs), and requiring either to install a desktop app
/// is not a bargain we get to make. Every pin we install has a wheel for every
/// platform we ship -- the one sdist-only dependency, hnswlib, is served as a
/// prebuilt wheel from `VENDOR_WHEELS_INDEX_URL` -- so in the healthy case this
/// flag changes nothing. It only bites when a wheel is *missing*: without it
/// pip silently falls back to the sdist and spends minutes compiling before
/// dying on a clang/cargo error no user can act on; with it pip fails at once
/// with "no matching distribution found", which `classify_bootstrap_failure`
/// already recognises and explains. Deliberately NOT applied to the optional
/// markitdown/serena addons: their transitive sets are unpinned and unaudited,
/// and a failed addon leaves a working Headroom behind.
const PIP_ONLY_BINARY: &str = "--only-binary=:all:";
// headroom binds on the backend port chosen at spawn time (default 6768);
// the intercept layer on 6767 forwards to it. The backend port is dynamic
// because something else on the machine (e.g. rapportd) can claim 6768 at
// login — see `backend_port` for the selection logic.
fn headroom_proxy_port() -> String {
    backend_port::get().to_string()
}
const HEADROOM_PROXY_URL: &str = "http://127.0.0.1:6767";
const MCP_METHOD_CLAUDE_CLI: &str = "claude_cli";
const MCP_METHOD_FALLBACK_JSON: &str = "fallback_json";
const MCP_METHOD_DIRECT_CLAUDE_JSON: &str = "direct_claude_json";
/// Installed for the other agents only: the Claude Code connector was off, so
/// its entry was taken back out (see `install_headroom_mcp`).
const MCP_METHOD_CLAUDE_CONNECTOR_OFF: &str = "claude_connector_off";

#[derive(Copy, Clone, Debug, PartialEq, Eq)]
enum McpInstallMethod {
    ClaudeCli,
    FallbackJson,
    DirectClaudeJson,
    ClaudeConnectorOff,
}

impl McpInstallMethod {
    fn as_str(self) -> &'static str {
        match self {
            McpInstallMethod::ClaudeCli => MCP_METHOD_CLAUDE_CLI,
            McpInstallMethod::FallbackJson => MCP_METHOD_FALLBACK_JSON,
            McpInstallMethod::DirectClaudeJson => MCP_METHOD_DIRECT_CLAUDE_JSON,
            McpInstallMethod::ClaudeConnectorOff => MCP_METHOD_CLAUDE_CONNECTOR_OFF,
        }
    }
}
const HEADROOM_STARTUP_POLL_MS: u64 = 250;
const HEADROOM_STARTUP_TIMEOUT_MS: u64 = 300_000;
/// `connect_local_proxy`'s connect timeout. Windows retries the SYN on a
/// refused loopback connect, so there every startup poll waits this out too.
const LOCAL_PROXY_PROBE_TIMEOUT_MS: u64 = 180;
/// When the Windows startup loop gives up: it counts polls, not time, and each
/// one waits out the probe's timeout, so it runs ~516s, not 300s.
const WINDOWS_STARTUP_LOOP_MS: u64 = HEADROOM_STARTUP_TIMEOUT_MS / HEADROOM_STARTUP_POLL_MS
    * (HEADROOM_STARTUP_POLL_MS + LOCAL_PROXY_PROBE_TIMEOUT_MS);
/// When a backend that has not bound its port dumps its stacks: 30s before
/// the Windows startup loop kills it, room for the interpreter's own start
/// before the sitecustomize arms the timer. Keyed to the nominal 300s, it
/// fired at 270s in backends still on their way to a healthy bind up to ~516s.
const STARTUP_STALL_DUMP_SECS: u64 = WINDOWS_STARTUP_LOOP_MS / 1000 - 30;

/// The env that arms the sitecustomize `startup_stall_dump` (RUST-P1). Windows
/// only: unix takes the same stacks with the SIGABRT sent at the startup
/// timeout. The dump reads other threads' frames without the GIL (why
/// `loop_stall_dump` is opt-in), so it fires only in a backend that has not
/// bound for `STARTUP_STALL_DUMP_SECS` and is killed at the timeout anyway.
fn startup_stall_dump_env(stall_path: &Path) -> Vec<(&'static str, std::ffi::OsString)> {
    if !cfg!(windows) {
        return Vec::new();
    }
    vec![
        ("HEADROOM_STARTUP_STALL_DUMP", stall_path.into()),
        (
            "HEADROOM_STARTUP_STALL_DUMP_SECS",
            STARTUP_STALL_DUMP_SECS.to_string().into(),
        ),
    ]
}

/// Third-party TLS clients in the backend (huggingface_hub model pulls,
/// tiktoken vocab) verify against the OS store, so a corporate proxy or
/// antivirus that re-signs HTTPS does not fail them with
/// CERTIFICATE_VERIFY_FAILED. The 0.41.0 wheel injects truststore process-wide
/// from its `headroom` CLI (the primary entrypoint, every platform), but the
/// `python -m headroom.proxy.server` fallback only under
/// `HEADROOM_PROCESS_TRUST=1`. macOS and Windows only, as the sitecustomize
/// os_truststore vendor it replaces was: a Linux box without ca-certificates
/// would lose public roots. `HEADROOM_CERT_STORE=bundled` opts out on both
/// entrypoints (the old `HEADROOM_OS_TRUSTSTORE=0`).
fn process_trust_env() -> Vec<(&'static str, &'static str)> {
    if cfg!(any(target_os = "macos", windows)) {
        vec![("HEADROOM_PROCESS_TRUST", "1")]
    } else {
        Vec::new()
    }
}

/// The bundle to hand the backend as the additive `HEADROOM_CA_BUNDLE`. Since
/// 0.40.0 `SSL_CERT_FILE` / `REQUESTS_CA_BUNDLE` REPLACE the trust store and
/// skip process trust, where the 0.39.0 os_truststore vendor loaded them on top
/// of the OS store. Our own bootstrap remediation tells users to set both, and
/// a bundle holding only the company root would fail every host the company
/// does not re-sign (off VPN, say). macOS and Windows, as process_trust_env;
/// HEADROOM_CERT_STORE is left alone. A user's own HEADROOM_CA_BUNDLE is kept,
/// but the replacing vars still go: the wheel checks them first and would
/// never load it. Same first-existing-file order as the wheel's
/// `find_ca_bundle`. A pre-0.40 runtime (a failed upgrade rolled back to it)
/// has no HEADROOM_CA_BUNDLE, so it keeps the replacing vars: removed, it
/// would trust certifi alone.
fn additive_ca_bundle(
    installed_version: Option<&str>,
    var: impl Fn(&str) -> Option<String>,
) -> Option<String> {
    let set = |name: &str| var(name).filter(|value| !value.trim().is_empty());
    if !cfg!(any(target_os = "macos", windows))
        || !runtime_version_at_least(installed_version, (0, 40))
        || set("HEADROOM_CERT_STORE").is_some()
    {
        return None;
    }
    let replacing = ["SSL_CERT_FILE", "REQUESTS_CA_BUNDLE"]
        .into_iter()
        .filter_map(set)
        .find(|path| Path::new(path).is_file())?;
    Some(set("HEADROOM_CA_BUNDLE").unwrap_or(replacing))
}

const HEADROOM_REQUIREMENTS_LOCK: &str = include_str!("../python/headroom-requirements.lock");
const HEADROOM_LINUX_REQUIREMENTS_LOCK: &str =
    include_str!("../python/headroom-linux-requirements.lock");
const HEADROOM_WINDOWS_REQUIREMENTS_LOCK: &str =
    include_str!("../python/headroom-windows-requirements.lock");

/// Full-file SHA-256 values of historical headroom-requirements.lock shipments
/// whose pinned versions are byte-for-byte identical to the current lock.
/// Receipts holding one of these shas are treated as up-to-date; the receipt is
/// silently migrated to the comment-insensitive sha on next launch so the
/// entry can be dropped the next time the lock file actually changes.
///
/// When modifying the lock, re-evaluate: compare the stripped (comments and
/// blank lines removed) form of each legacy lock against the stripped current
/// lock. Drop any entry that no longer matches — those users need a real
/// reinstall.
const LEGACY_REQUIREMENTS_LOCK_SHAS: &[&str] = &[
    // 0.28.0 re-resolved the lock from scratch ([all,vector], torch 2.12.1,
    // benchmark tail dropped, broad point-version churn), so its stripped sha
    // differs from every prior shipment. The 0.27.0 cohort's lock receipt is now
    // genuinely stale and SHOULD trigger a dep reinstall — do not whitelist the
    // old sha here. The list stays empty until a future no-op cosmetic lock edit
    // (comments/blank lines only, no pin moves) needs to be treated as
    // up-to-date.
];

/// Receipts strictly below this version cannot be safely upgraded in place to
/// the currently bundled headroom-ai — pip's in-place upgrade leaves stale
/// `.so`/`.dylib` files from old native-extension pins (onnxruntime,
/// tokenizers, cryptography, mmh3, py_rust_stemmers, uvloop/httptools)
/// alongside the new ones, which surfaces as "smoke test passes, boot
/// validation fails with no log lines and no port bound" — the python
/// process segfaults on import before reaching logging setup.
///
/// Bumping this floor is a release-by-release decision: when a new lock
/// adds native deps or bumps native pins ABI-incompatibly, raise the floor
/// to the previous bundled version. When the new lock only churns pure-Python
/// pins, leave the floor where it is.
///
/// Floor history:
/// - 0.3.7: set to 0.10.0. 0.3.6's lock jump from 0.8.2 → 0.19.0 added
///   fastembed/mmh3/py_rust_stemmers and bumped tokenizers/cryptography/
///   uvicorn; the failing Sentry users all had `fallback: 0.8.2` (from
///   0.2.50-era desktop). 0.3.0-rc.26 onward shipped headroom-ai 0.10.x
///   against the same lock as 0.8.2 — these users have the same dep set
///   on disk and have not produced upgrade-failure events, so we let them
///   take the cheap in-place path. If 0.10.x fallbacks start appearing in
///   Sentry, raise the floor.
/// - 0.3.8: a single `fallback: 0.10.12` boot-validation stall appeared in
///   Sentry, but a clean-VM 0.3.5 → 0.3.7 upgrade reproduced the same
///   0.10.12 → 0.19.0 in-place delta and succeeded. The N=1 failure looks
///   environmental, not universal to the 0.10.x cohort. With the new
///   "Retry with full rebuild" button as a recovery path for the
///   environmental cases, we keep the floor at 0.10.0 rather than penalize
///   the (probably ~99%) of 0.10.x users who succeed in-place. Re-evaluate
///   if multi-machine 0.10.x failures show up in 0.3.8 telemetry.
/// - 0.4.0: raised to 0.20.0. Upstream 0.20.x switched headroom-ai to a
///   maturin/Rust-native single-wheel build (upstream #355) — wheels are now
///   per-Python-version and per-platform and ship a compiled `headroom_core`
///   `.so`. 0.19.0 venvs were built against a `py3-none-any` wheel with no
///   native extension; an in-place pip upgrade onto the new wheel would
///   layer the new `.so` on top of stale transitive native pins from the
///   old lock, which is the exact segfault-on-import pattern this floor
///   exists to prevent. Atomic rebuild is the only safe path for the
///   0.10.x–0.19.x cohort on this bump.
/// - 0.4.2 (0.24.0 → 0.25.0 bundle): floor stays at 0.20.0. The lock delta is
///   two pure-Python pins (litellm, importlib-metadata); no native pin moves
///   and no native dep is added or removed. The headroom-ai wheel itself goes
///   from a per-version `cp312-cp312` native wheel to a stable-ABI `cp310-abi3`
///   wheel (upstream #516), but pip uninstalls the old wheel (clearing its
///   `cpython-312` `.so` via RECORD) before unpacking the new `abi3` `.so`, so
///   no stale headroom_core extension is layered. The 0.20.x+ cohort — which
///   includes every 0.24.0-shipping (desktop 0.4.1) user — upgrades in place
///   with no big-wheel rebuilds. Raise the floor only if a future lock adds or
///   ABI-bumps a native transitive dep.
/// - 0.4.x (0.25.0 → 0.26.0 bundle): floor stays at 0.20.0. headroom-ai's
///   `requires_dist` is byte-identical between 0.25.0 and 0.26.0, so the lock
///   is reused unchanged — no pin moves at all. pip uninstalls the 0.25.0 abi3
///   wheel (clearing its `.so` via RECORD) and unpacks the 0.26.0 abi3 wheel;
///   no stale native extension is layered. The 0.20.x+ cohort upgrades in
///   place with no wheel rebuilds.
/// - 0.4.x (0.26.0 → 0.27.0 bundle): floor stays at 0.20.0. The lock moves three
///   pins: tree-sitter-language-pack 1.8.1 → 0.13.0 (native, ships compiled
///   grammar `.so`s) and the new spreadsheet extra (et-xmlfile/openpyxl/xlrd,
///   pure-Python). The language-pack move is a version *change*, so pip
///   uninstalls 1.8.1 via its RECORD (removing the old grammar `.so`s) before
///   unpacking 0.13.0 — no stale native extension is layered, unlike the
///   same-version in-place rebuilds this floor guards against. headroom-ai's own
///   abi3 wheel is likewise uninstalled-then-reinstalled. The 0.20.x+ cohort
///   upgrades in place. Raise the floor only if a future lock adds or
///   ABI-bumps a native transitive dep without a version bump.
/// - 0.5.x (0.27.0 → 0.28.0 bundle): floor stays at 0.20.0. Native pin moves are
///   all version *changes* (torch 2.11.0 → 2.12.1, onnxruntime 1.23.2 → 1.27.0),
///   so pip uninstalls the old wheel via RECORD (clearing its `.so`) before
///   unpacking the new one — no same-version relayering. The new tree-sitter
///   grammar packages (tree-sitter-c-sharp/embedded-template/yaml) are fresh
///   installs, not in-place rebuilds, so they carry no stale-`.so` risk either.
///   hnswlib stays pinned at 0.8.0 (unchanged). The benchmark-tail packages
///   dropped from the lock are pure-Python orphans left on disk by the in-place
///   `--upgrade` (pip does not prune removed requirements); harmless. The
///   0.20.x+ cohort upgrades in place.
/// - 0.7.x (0.32.1 → 0.33.0 bundle): floor stays at 0.20.0. The lock is
///   unchanged — 0.33.0's requires_dist only *tightens* three existing
///   constraints (ast-grep-cli !=0.44.1, mcp >=1.28.1,<2.0.0 on the mcp/proxy
///   extras, ruff on the dev extra), and the shipped lock already satisfies all
///   of them (ast-grep-cli==0.44.0, mcp==1.28.1; dev isn't installed). No
///   package is added or removed from the core/extra set we install, so the
///   in-place path is a single `pip install --no-deps --force-reinstall` of the
///   abi3 wheel with zero dep churn. The new Rust ports (CodeCompressor,
///   Kompress — upstream #1154/#1153) live inside headroom-ai's own
///   `headroom_core` abi3 extension, which pip uninstalls via RECORD before
///   unpacking the replacement, so no stale `.so` is layered.
/// - 0.7.x (0.33.0 → 0.34.0 bundle): floor stays at 0.20.0. requires_dist is
///   byte-identical to 0.33.0. The lock tops up two transitive pins to match
///   upstream's #2753 CVE clearance (aiohttp 3.14.1 → 3.14.3, cryptography
///   49.0.0 → 50.0.0). Both are version *changes* of native wheels, so pip
///   uninstalls the old wheel via RECORD before unpacking the new one — no
///   same-version relayering. The lock-sha change triggers a dep top-up for
///   existing users, which is intended (they need the CVE-fixed wheels).
/// - 0.8.x (0.34.0 → 0.35.0 bundle): floor stays at 0.20.0. requires_dist
///   only moves the ruff dev pin (dev extra isn't installed). The lock tops
///   up one transitive pin to match upstream's #2839 CVE clearance: h2
///   4.3.0 → 4.4.1 (CVE-2026-71554). h2 is pure-Python, and its hpack/
///   hyperframe requirements are already satisfied by the shipped pins, so
///   the top-up is a wheel swap with no native or resolution churn.
const ATOMIC_REBUILD_FLOOR_VERSION: (u32, u32, u32) = (0, 20, 0);

/// Parse the leading `major.minor.patch` from a version string, tolerating
/// pre-release/build suffixes (`-rc.1`, `+build`, `.dev0`, etc.). Returns
/// None when the prefix isn't a numeric `major.minor`. `patch` defaults to
/// 0 when missing or unparseable, so `"0.19"` and `"0.19.0"` compare equal.
/// Injected onto the backend's PYTHONPATH so the `site` module imports it at
/// interpreter startup. `faulthandler.register` needs Python-side code — the
/// PYTHONFAULTHANDLER env only covers fatal signals — and the upstream proxy
/// has no dump hook of its own.
const SITECUSTOMIZE_PY: &str = r#""""Headroom Desktop injection (managed -- do not edit).

Registers SIGUSR1 to dump all Python thread stacks to stderr (the proxy
log). The desktop watchdog sends SIGUSR1 before force-killing a wedged
backend so the log shows what the event loop was stuck on.

Also keeps user-turn text out of lossy compression: from headroom-ai
0.34.0 the "coding" persona sets compress_user_messages=True, and the
profile kwargs force it on per request (HEADROOM_COMPRESS_USER_MESSAGES
can only force-enable, never disable), so the persona field itself is
flipped back. Verbatim user turns are deliberate desktop posture, not a
bug workaround: user messages carry the coding working set (code, errors,
paths) and Claude Code's <system-reminder> blocks (CLAUDE.md), which the
model must see verbatim. The 0.34.0 tag-split bug that made this urgent
(open/close tags landing in different router sections, so the pair never
matched and CLAUDE.md arrived word-dropped) was fixed upstream in 0.35.0
(#2887), but that only protects TAGGED blocks -- plain user text would
still compress -- so the flip stays. tool_result blocks compress
regardless of this flag (the role gate only guards text blocks), so the
coding token mass is unaffected.

Also carries three proxy-side guards, gated on
HEADROOM_SDK=headroom-desktop-proxy so only the backend process pays the
proxy import cost:
Tool-schema dollar unfold: since the 0.36.0
attribution unification, record_request folds the priced tool-schema
bucket into compression_savings_usd (lifetime, display_session,
per-model, per-project, and every history checkpoint) while the token
fields beside them stay message-only, so any $/token read on the
persisted state is inflated by 1 + tool/message -- 5.59x tool/message
measured on one real install, an implied $32.88/M next to models that
list at $10/M input. The desktop accumulates lifetime savings from
these dollar fields, so the fold would contaminate the headline the
product is trusted for (the savings-rate canary in state.rs is the
runtime tripwire for exactly this). The guard zeroes the tool_schema
bucket before the fold, restoring the 0.35.0 meaning of every
persisted dollar field; tool-schema TOKENS are untouched and the
desktop keeps pricing those itself at the cache-read rate. #3170
(0.40.0) only added a disjoint field beside the fold, so the guard
stands down when record_request stops summing the two buckets. Kill
switch: HEADROOM_SAVINGS_FOLD_GUARD=0.
Prefix-replay inflation-skip guard (upstream issue #3379): since the
0.36.x non-inflation bound (#3052), overlay_cached_prefix declines to
replay the previously-forwarded prefix whenever background compression
lands a SMALLER form of already-forwarded history, so the forwarded
bytes change mid-conversation and the provider prompt cache busts from
the first changed byte -- measured 2026-09-01 as a 160-210k-token cache
re-write every 1-2 requests, dollar cache-hit rate 90% -> 52%, billable
input $/M up 2.2x, across the 0.35.0 -> 0.37.0 wheel swap. The guard
restores the 0.35.0 replay policy wholesale: v0.35.0's prefix_tracker
carries NO size bound at all (`_compact_json_bytes` does not exist
there), so it replayed the cached prefix whenever alignment allowed.
The bound arrived with #3052 and is what declines -- and a decline over
already-cached bytes IS the bust. A floor-limited port was shipped in
0.9.4 and measured WORSE than no guard: replaying only up to the
confirmed floor leaves every byte past it free to bust, and the fleet
lost 22% of cache coverage (1.20 -> 0.94 reads/sent, n=17, p=0.007)
against 4% for users who stayed on 0.9.3. Full replay is the state that
measured 26% input savings on 0.35.0, so the guard reproduces exactly
that and nothing cleverer. Gated on the
runtime NOT having the fix's parameter (enforce_non_inflation in the
first PR shape, confirmed_frozen_count in the reworked #3380 shape), so
the first wheel that ships either keeps its own replay policy and this
block goes inert. Kill switch: HEADROOM_PREFIX_REPLAY_GUARD=0. Inert
since the 0.38.0 pin: that wheel ships #3380 (confirmed_frozen_count), so
the guard is only the fallback for a wheel that lost the fix.
cc-switch Official-branch upstream reset (upstream PR #3166): the
reconciler captures the third-party endpoint cc-switch selected (Kimi,
DeepSeek, GLM) as this proxy's Anthropic upstream, but switching back to
Claude Official only stops it rewriting settings.json -- the captured
endpoint stays live on HeadroomProxy.ANTHROPIC_API_URL, a process-wide
class attr, so every Anthropic client still routed through this proxy
keeps reaching the old provider while sending Anthropic OAuth
credentials. The guard resets the upstream to the default when
settings.json goes back to an empty env, and only when this reconciler
is the one that captured a non-default upstream (an operator-configured
upstream is left alone). Unlike the other two this one is load-bearing,
not corrective: the desktop sets HEADROOM_CC_SWITCH_RECONCILE=1 only
because the guard binds here, so every failure path -- kill switch,
missing module, renamed method -- clears that env before the proxy reads
it, and the reconciler stays off instead of running unfixed. No version
gate: the reset is native since 0.41.0 (#3166), whose tick has already
reset the upstream by the time the wrapper looks, so there the wrapper
only ends the capture file the reset left behind. Kill switch:
HEADROOM_CC_SWITCH_RESET_GUARD=0, which turns the reconciler off with
it.
The same guard pins the URL the reconciler advertises to clients.
Upstream builds it from the port this proxy bound -- the internal port
between the desktop intercept and this process -- so every provider
switch rewrote the client onto that port and out of the intercept, where
the activity feed, request counts and savings accounting live. The
desktop passes the intercept URL in HEADROOM_CC_SWITCH_PROXY_URL and the
guard writes it onto every reconciler instance. Because that replaces the
string upstream's loop guard matches, the guard also refuses this proxy's
own address (localhost, the internal port) as an upstream. And it records
each capture in HEADROOM_CC_SWITCH_CAPTURE_PATH: the desktop restores
settings.json on quit and pause after this process is gone, so an
in-memory capture was lost and the provider's key went to
api.anthropic.com; the next instance reseeds from the same file. It
reconciles only while the cc-switch-routed file beside it exists, which the
desktop keeps in step with the Claude Code connector.

Also stops the traffic learner writing "Learned: error recovery" into the
user's Claude Code MEMORY.md. It pairs any failed tool call with the next
success regardless of intent, so the bullets are wrong ("grep X fails, use
sed on an unrelated file instead"), and multi-line Bash commands land
verbatim. MEMORY.md is the auto-memory index Claude Code truncates at 200
lines, so up to 15 such bullets pushed the user's own entries off the end.
The desktop's launch scrub (memory_scrubber.rs) only cleaned it between
flushes. Environment/architecture (CLAUDE.md) and preference routing are
untouched. Kill switch: HEADROOM_LEARN_DROP_ERROR_RECOVERY=0.

Also bounds learn's `codex exec` connection retries, so a dead route fails
in seconds with codex's own reason instead of waiting out the 900s cap
(RUST-P2). Kill switch: HEADROOM_LEARN_CODEX_RETRIES=0.

Can also write the serving loop's stack to logs/loop-stall.txt when the
event loop stalls (desktop diagnostic, RUST-86). Off unless
HEADROOM_LOOP_STALL_DUMP is set to a positive number of seconds.

Can also write every thread's stack to HEADROOM_STARTUP_STALL_DUMP when the
proxy has not bound its port HEADROOM_STARTUP_STALL_DUMP_SECS after start
(desktop diagnostic, RUST-P1). The desktop sets both on Windows only.
"""
import faulthandler
import os as _hd_os
import signal
import sys as _hd_sys

# No chain=True: SIGUSR1's default disposition is terminate, and chaining
# falls through to it after the dump -- the process must survive the dump so
# the watchdog controls the actual kill.
try:
    faulthandler.register(signal.SIGUSR1, all_threads=True)
except Exception:
    pass

# Names of the patches below that bound in this process; summarized once at
# the end (see _HD_VENDORS).
_hd_bound = set()

# --- Pre-bind stall dump (desktop diagnostic, RUST-P1) ------------------------
# A backend that never binds its port is killed at the desktop's startup
# timeout. On unix that kill starts with SIGABRT, so faulthandler leaves every
# thread's stack in the log; Windows has no such signal, and RUST-P1 arrived
# with a banner and nothing after it (the wheel sends its own records after
# create_app only to ~/.headroom/logs/proxy-<port>.log). faulthandler's C
# timer writes the stacks to the desktop's file instead, unless uvicorn's
# startup returns first (port bound), which cancels it. Armed here, before any
# vendor below imports headroom, so a stall in those imports is covered too.
# One-shot, and it fires only in a backend that has not bound for 270s, which
# the desktop then kills (taskkill /F), so the crash risk that keeps
# loop_stall_dump opt-in costs nothing here; the wedge risk is handled where
# startup cancels it.
if _hd_os.environ.get("HEADROOM_SDK") == "headroom-desktop-proxy" and _hd_sys.argv[:1] != ["-c"]:
    try:
        # Popped: this process's timer only, never a child Python's.
        _hd_ss_path = _hd_os.environ.pop("HEADROOM_STARTUP_STALL_DUMP", "")
        _hd_ss_secs = _hd_os.environ.pop("HEADROOM_STARTUP_STALL_DUMP_SECS", "")
        if _hd_ss_path:
            # O_BINARY: see loop_stall_dump.
            _hd_ss_fd = _hd_os.open(
                _hd_ss_path,
                _hd_os.O_WRONLY | _hd_os.O_CREAT | _hd_os.O_TRUNC | getattr(_hd_os, "O_BINARY", 0),
                0o600,
            )
            faulthandler.dump_traceback_later(float(_hd_ss_secs), file=_hd_ss_fd)
            import uvicorn.server as _hd_ss_uv

            _hd_ss_orig_startup = _hd_ss_uv.Server.startup

            async def _hd_ss_startup(self, *args, **kwargs):
                try:
                    return await _hd_ss_orig_startup(self, *args, **kwargs)
                finally:
                    # Not once the dump has begun: its GIL-free frame walk can
                    # spin forever on a main thread that is busy running Python
                    # (seen mid-import), and cancel waits on it with the GIL
                    # held, which would wedge a backend that bound late. A late
                    # bind after a spun dump keeps the spinning thread instead.
                    # ponytail: that thread burns a core until the process
                    # exits; a GIL-holding sampler cannot see a GIL-holding
                    # native stall (a DLL load), which is the case this is for.
                    try:
                        fired = _hd_os.fstat(_hd_ss_fd).st_size > 0
                    except OSError:
                        fired = False
                    if not fired:
                        faulthandler.cancel_dump_traceback_later()

            _hd_ss_uv.Server.startup = _hd_ss_startup
            _hd_bound.add("startup_stall_dump")
    except Exception:
        # Never leave a timer that nothing will cancel.
        faulthandler.cancel_dump_traceback_later()

# Protect user-turn text (CLAUDE.md system-reminders) from lossy Kompress:
# flip the coding persona back to compress_user_messages=False. Guarded so
# fallback runtimes without the persona (< 0.30.0) and half-installed venvs
# no-op cleanly.
try:
    from dataclasses import replace as _hd_replace

    import headroom.agent_savings as _hd_savings

    _hd_coding = _hd_savings._PROFILES.get("coding")
    if _hd_coding is not None and _hd_coding.compress_user_messages:
        _hd_savings._PROFILES["coding"] = _hd_replace(
            _hd_coding, compress_user_messages=False
        )
        _hd_bound.add("user_turn_verbatim")
except Exception:
    pass

if _hd_os.environ.get("HEADROOM_SDK") == "headroom-desktop-proxy":
    # Tool-schema dollar unfold (see the module docstring for the
    # contamination this prevents). The wrapper strikes at the single choke
    # point every caller funnels through: SavingsTracker.record_request is
    # keyword-only, and the fold is priced["compression"] +
    # priced["tool_schema"] inside it. Zeroing the tool_schema bucket on a
    # COPY (the caller's mapping is never mutated) restores message-only
    # dollars everywhere the tracker persists them, while tool_search_saved --
    # the token side -- passes through untouched. Gated on the fold itself, not
    # on #3170's disjoint field: 0.40.0 added tool_schema_savings_usd beside
    # the folded dollars but kept the fold, so a field-presence gate stood the
    # guard down while the desktop, which deltas the folded field and prices
    # tool-schema itself, counted those dollars twice. Under the guard the
    # wheel's disjoint tool_schema_savings_usd reads 0; no desktop code reads
    # it. Kill switch: HEADROOM_SAVINGS_FOLD_GUARD=0.
    try:
        if _hd_os.environ.get(
            "HEADROOM_SAVINGS_FOLD_GUARD", "1"
        ).strip().lower() not in ("0", "false", "no", "off"):
            import inspect as _hd_sf_inspect

            import headroom.proxy.savings_tracker as _hd_sf_st

            if "compression_usd + tool_schema_usd" in _hd_sf_inspect.getsource(
                _hd_sf_st.SavingsTracker.record_request
            ):
                _hd_sf_orig_record = _hd_sf_st.SavingsTracker.record_request

                def _hd_sf_record(self, **kwargs):
                    priced = kwargs.get("estimated_savings_usd")
                    if priced is not None:
                        try:
                            unfolded = dict(priced)
                            unfolded["tool_schema"] = 0.0
                            kwargs["estimated_savings_usd"] = unfolded
                        except Exception:
                            pass
                    return _hd_sf_orig_record(self, **kwargs)

                _hd_sf_st.SavingsTracker.record_request = _hd_sf_record
                _hd_bound.add("savings_fold_guard")
    except Exception:
        pass

    # Observe confirmed prefix rewrites independently of the replay/lineage
    # fixes. Only numeric diagnostics cross /stats to the desktop's Sentry SDK.
    # No provider calls, disk writes, or request mutations in this observer.
    # resolve_tracker is wrapped pass-through for every argument: 0.41.0's
    # Anthropic handler passes cache_ttl_seconds, and a wrapper with the old
    # four-argument signature raised TypeError on every Anthropic request.
    try:
        from importlib import metadata as _hd_ci_meta
        if (_hd_ci_meta.version("headroom-ai") == "0.41.0" and
            _hd_os.environ.get("HEADROOM_CACHE_INTEGRITY", "1").strip().lower()
                not in ("0", "false", "no", "off")):
            import contextvars as _hd_ci_cv
            import time as _hd_ci_time
            import uuid as _hd_ci_uuid
            import sys as _hd_ci_sys
            from headroom.cache import prefix_tracker as _hd_ci_pt
            from headroom.proxy import cost as _hd_ci_cost
            _hd_ci_pending = _hd_ci_cv.ContextVar("desktop_cache_integrity", default=None)
            _hd_ci_stats = {"boot_id": _hd_ci_uuid.uuid4().hex, "count": 0}
            _hd_ci_resolve = _hd_ci_pt.SessionTrackerStore.resolve_tracker
            _hd_ci_update = _hd_ci_pt.PrefixCacheTracker.update_from_response
            _hd_ci_build_stats = _hd_ci_cost.build_prefix_cache_stats

            def _hd_ci_resolve_tracker(self, session_id, provider, messages=None,
                                       cache_affinity=None, *args, **kwargs):
                _hd_ci_pending.set(None)
                tracker = _hd_ci_resolve(self, session_id, provider, messages, cache_affinity,
                                         *args, **kwargs)
                try:
                    if provider != "anthropic" or not messages or not self._default_config.enabled:
                        return tracker
                    prior = tracker
                    if not prior.get_frozen_message_count():
                        # A lost tracker has no history to check. Recover evidence
                        # ONLY for the proven disappearing-system-tail shape;
                        # arbitrary sibling branches must not raise an alarm.
                        snap = _hd_ci_pt._lineage_snapshot(
                            _hd_ci_pt._canonicalize_for_prefix_compare(messages))
                        candidates = []
                        for key, chain in self._lineages.get(session_id, {}).items():
                            candidate = self.peek(key)
                            if (candidate is None or candidate is tracker
                                or self._lineage_affinities.get(key) != cache_affinity
                                or not candidate.get_frozen_message_count()):
                                continue
                            if (len(chain) > 1 and chain[-1].get("role") == "system"
                                and any(m.get("role") in ("user", "assistant") for m in chain[:-1])
                                and len(snap) >= len(chain) and snap[:len(chain)-1] == chain[:-1]):
                                candidates.append((len(chain), key, candidate))
                        candidates.sort(key=lambda x: x[0], reverse=True)
                        if not candidates or (len(candidates) > 1 and candidates[0][0] == candidates[1][0]):
                            return tracker
                        prior = candidates[0][2]
                    idle = (prior._idle_seconds_at_fetch if prior is tracker
                            else prior.seconds_since_activity())
                    ttl = prior.resolved_cache_ttl_seconds()
                    if idle >= ttl or not prior.get_frozen_message_count():
                        return tracker
                    original = prior._last_original_messages
                    frozen = prior.get_frozen_message_count()
                    # The handler appends the assistant RESPONSE to tracker
                    # history. Those bytes were never in the previous request;
                    # an estimated floor can overshoot into this fresh message.
                    if original and original[-1].get("role") == "assistant":
                        frozen = min(frozen, len(original) - 1)
                    # Tracker updates replace these lists instead of mutating
                    # them. Hold references for this request, not another copy
                    # of a potentially million-token conversation.
                    _hd_ci_pending.set((tracker, original,
                        prior._last_forwarded_messages, frozen,
                        prior._cached_token_count, _hd_ci_time.monotonic() + ttl - idle,
                        prior is not tracker))
                except Exception:
                    pass
                return tracker

            def _hd_ci_update_tracker(self, cache_read_tokens, cache_write_tokens, messages,
                                      message_token_counts=None, original_messages=None):
                evidence = _hd_ci_pending.get()
                _hd_ci_pending.set(None)
                try:
                    if (evidence is not None and evidence[0] is self
                        and original_messages and cache_write_tokens > 0
                        and cache_read_tokens < evidence[4]
                        and _hd_ci_time.monotonic() < evidence[5]):
                        _, old_original, old_forwarded, frozen, expected, _, reset = evidence
                        stable = 0
                        first_changed = None
                        canon = _hd_ci_pt._canonicalize_for_prefix_compare
                        for i in range(min(frozen, len(old_original), len(old_forwarded),
                                           len(original_messages), len(messages))):
                            if canon([old_original[i]]) != canon([original_messages[i]]):
                                break
                            stable += 1
                            if first_changed is None and canon([old_forwarded[i]]) != canon([messages[i]]):
                                first_changed = i
                        if first_changed is not None:
                            _hd_ci_stats.update(count=_hd_ci_stats["count"] + 1,
                                kind="tracker_reset" if reset else "prefix_rewrite",
                                stable_messages=stable, first_changed_message=first_changed,
                                previously_cached_tokens=expected,
                                cache_read_tokens=cache_read_tokens,
                                cache_write_tokens=cache_write_tokens)
                except Exception:
                    pass
                return _hd_ci_update(self, cache_read_tokens, cache_write_tokens, messages,
                                     message_token_counts, original_messages)

            def _hd_ci_prefix_stats(*args, **kwargs):
                result = _hd_ci_build_stats(*args, **kwargs)
                result["desktop_integrity"] = dict(_hd_ci_stats)
                return result

            _hd_ci_pt.SessionTrackerStore.resolve_tracker = _hd_ci_resolve_tracker
            _hd_ci_pt.PrefixCacheTracker.update_from_response = _hd_ci_update_tracker
            _hd_ci_cost.build_prefix_cache_stats = _hd_ci_prefix_stats
            _hd_bound.add("cache_integrity")
            # Usually server imports cost after sitecustomize; cover an already
            # loaded server too without importing it just for instrumentation.
            _hd_ci_server = _hd_ci_sys.modules.get("headroom.proxy.server")
            if _hd_ci_server is not None:
                # 0.41.0's /stats calls this name (0.39.0 had a _-prefixed alias).
                _hd_ci_server.build_prefix_cache_stats = _hd_ci_prefix_stats
    except Exception:
        pass

    # Prefix-replay guard (upstream issue #3379 / PR #3380; remove once a
    # wheel ships the fix -- see the module docstring for the cache-bust loop
    # this prevents). Restores v0.35.0's policy: that release has no size
    # bound at all, so it replayed the cached prefix whenever alignment
    # allowed. The bound (#3052) declines instead, and declining over
    # already-cached bytes is the bust. Probed by calling the original twice
    # on DECLINED turns only: once bound-on (a shrinking repair is accepted
    # as-is), once with _compact_json_bytes stubbed to equal-length bytes so
    # the inflation compare goes false while every alignment guard still
    # runs. Overlay is synchronous on the proxy's single event loop, so the
    # stub swap cannot interleave. Gated on the runtime
    # NOT having the fix's parameter under either name shipped on #3380
    # (enforce_non_inflation / confirmed_frozen_count), so the first wheel
    # that ships the fix keeps its own replay policy and this block goes
    # inert. Kill switch: HEADROOM_PREFIX_REPLAY_GUARD=0. Inert on the
    # 0.38.0 pin, which ships #3380's confirmed_frozen_count; binds only on
    # a wheel that lost the fix.
    try:
        if _hd_os.environ.get(
            "HEADROOM_PREFIX_REPLAY_GUARD", "1"
        ).strip().lower() not in ("0", "false", "no", "off"):
            import headroom.cache.prefix_tracker as _hd_pr_pt

            _hd_pr_fixed = any(
                name in _hd_pr_pt.overlay_cached_prefix.__code__.co_varnames
                for name in ("enforce_non_inflation", "confirmed_frozen_count")
            )
            if hasattr(_hd_pr_pt, "_compact_json_bytes") and not _hd_pr_fixed:
                _hd_pr_orig_overlay = _hd_pr_pt.overlay_cached_prefix

                def _hd_pr_overlay(*args, **kwargs):
                    optimized = args[0] if args else kwargs.get("optimized_messages")
                    # Pass 1, bound enforced -- identical to stock. A repair
                    # that shrinks (freeze drift, #1850) is accepted as-is.
                    r1 = _hd_pr_orig_overlay(*args, **kwargs)
                    if r1 is not optimized:
                        return r1
                    # Pass 2, bound neutered; every alignment guard still
                    # runs, so a replay that is not provably correct still
                    # returns optimized untouched. Reached only on declined
                    # turns (post-kompress, a few per minute at most).
                    _hd_pr_saved = _hd_pr_pt._compact_json_bytes
                    _hd_pr_pt._compact_json_bytes = lambda value: b""
                    try:
                        return _hd_pr_orig_overlay(*args, **kwargs)
                    finally:
                        _hd_pr_pt._compact_json_bytes = _hd_pr_saved

                _hd_pr_pt.overlay_cached_prefix = _hd_pr_overlay
                _hd_bound.add("prefix_replay_guard")
    except Exception:
        pass

    # cc-switch Official-branch upstream reset (upstream PR #3166, native since
    # 0.41.0; the intercept URL, self-loop guard, pin, capture file and routed
    # gate below are desktop posture -- see the module docstring for the
    # misroutes these prevent). Load-bearing: the desktop opts into the
    # reconciler ONLY because this binds, so every failure path below clears
    # HEADROOM_CC_SWITCH_RECONCILE, which the proxy reads later
    # (reconciler_enabled(), at app creation) -- fail closed, not unfixed.
    try:
        if _hd_os.environ.get(
            "HEADROOM_CC_SWITCH_RESET_GUARD", "1"
        ).strip().lower() in ("0", "false", "no", "off"):
            raise RuntimeError("cc-switch reset guard disabled by env")

        import inspect as _hd_ccs_inspect
        import json as _hd_ccs_json
        import logging as _hd_ccs_logging

        import headroom.proxy.cc_switch_reconciler as _hd_ccs_mod

        _hd_ccs_log = _hd_ccs_logging.getLogger("headroom.proxy")
        _hd_ccs_orig_tick = _hd_ccs_mod.CCSwitchReconciler.tick
        # The wrapper reads four instance attributes the constructor names.
        # Checking them here means a runtime that renamed any of them fails
        # closed at bind time, instead of binding a wrapper whose every tick
        # raises into the swallow below and silently leaves the upstream stale.
        _hd_ccs_params = _hd_ccs_inspect.signature(
            _hd_ccs_mod.CCSwitchReconciler.__init__
        ).parameters
        for _hd_ccs_needed in ("proxy_url", "default_upstream", "set_upstream", "path"):
            if _hd_ccs_needed not in _hd_ccs_params:
                raise RuntimeError(
                    "cc-switch reconciler no longer takes %r" % (_hd_ccs_needed,)
                )
        _hd_ccs_warned = False

        # Advertise the intercept port, not the port this process bound.
        # server.py builds the reconciler with
        # proxy_url=f"http://127.0.0.1:{config.port}", which is the INTERNAL
        # port between the desktop's intercept and this proxy (6768, or
        # 6769-6790 when something else already holds 6768). Clients belong on
        # the fixed intercept port: everything the desktop measures -- activity
        # feed, request counts, savings accounting, stale-tool-ref sanitisation
        # -- lives in the intercept, so a settings.json rewritten to the
        # internal port silently drops that client out of all of it, and breaks
        # outright on the next launch that has to take a fallback port. The
        # desktop passes the URL it wants advertised; no upstream knob exists
        # for this yet.
        _hd_ccs_url = _hd_os.environ.get("HEADROOM_CC_SWITCH_PROXY_URL", "").strip()
        if not _hd_ccs_url.startswith(("http://", "https://")):
            # Missing or malformed while the reconciler is enabled is an
            # inconsistent spawn, and guessing would write a bad base_url into
            # the user's settings.json. Fail closed with everything else.
            raise RuntimeError(
                "HEADROOM_CC_SWITCH_PROXY_URL missing or malformed: %r" % (_hd_ccs_url,)
            )
        _hd_ccs_url = _hd_ccs_url.rstrip("/")

        # Explicit upstream override (Override mode in the app). The user named
        # this endpoint, so a cc-switch capture must not move it; the
        # reconciler still rewrites settings.json, which is what keeps the
        # client on the intercept. Empty unless the desktop set both, so this
        # is inert for everyone else.
        _hd_ccs_pinned = ""
        if _hd_os.environ.get("HEADROOM_CC_SWITCH_PIN_UPSTREAM", "").strip().lower() in (
            "1",
            "true",
            "yes",
            "on",
        ):
            _hd_ccs_pinned = _hd_os.environ.get("ANTHROPIC_TARGET_API_URL", "").strip()
            if not _hd_ccs_pinned.startswith(("http://", "https://")):
                raise RuntimeError(
                    "pinned upstream missing or malformed: %r" % (_hd_ccs_pinned,)
                )

        # Where a capture is recorded for the desktop, as {"url": ...}: the base
        # URL this reconciler replaced in settings.json. The capture otherwise
        # lives only in this process, and the desktop restores settings.json on
        # quit and pause after this process is gone, so the provider URL was
        # deleted and its token sent to api.anthropic.com. Required like the
        # URL above; the next instance reseeds from it (see the tick).
        _hd_ccs_capture = _hd_os.environ.get("HEADROOM_CC_SWITCH_CAPTURE_PATH", "").strip()
        if not _hd_os.path.isabs(_hd_ccs_capture):
            raise RuntimeError(
                "HEADROOM_CC_SWITCH_CAPTURE_PATH missing or relative: %r" % (_hd_ccs_capture,)
            )
        # Beside it, present only while the desktop routes Claude Code's
        # settings.json (cc_switch_routed_path): a disable hands the file back,
        # and reconciling it then undid the connector toggle within 0.3s.
        _hd_ccs_routed = _hd_os.path.join(
            _hd_os.path.dirname(_hd_ccs_capture), "cc-switch-routed"
        )

        def _hd_ccs_save_capture(url):
            tmp = "%s.%d.tmp" % (_hd_ccs_capture, _hd_os.getpid())
            with open(tmp, "w", encoding="utf-8") as fh:
                _hd_ccs_json.dump({"url": url}, fh)
            _hd_os.replace(tmp, _hd_ccs_capture)

        def _hd_ccs_load_capture():
            try:
                with open(_hd_ccs_capture, encoding="utf-8") as fh:
                    url = _hd_ccs_json.load(fh).get("url")
            except (OSError, ValueError, AttributeError):
                return ""
            ok = isinstance(url, str) and url.startswith(("http://", "https://"))
            return url if ok else ""

        def _hd_ccs_drop_capture():
            try:
                _hd_os.remove(_hd_ccs_capture)
            except FileNotFoundError:
                pass

        from urllib.parse import urlsplit as _hd_ccs_urlsplit

        def _hd_ccs_port(url):
            try:
                return _hd_ccs_urlsplit(url or "").port
            except ValueError:
                return None

        def _hd_ccs_is_self(reconciler, url):
            # This proxy under any loopback spelling (localhost, the internal
            # port). Upstream's loop guard matches only the exact proxy_url,
            # which _hd_ccs_init replaces, so these were captured as the
            # upstream and every Anthropic request looped back into us.
            try:
                host = _hd_ccs_urlsplit(url or "").hostname
            except ValueError:
                return False
            own = getattr(reconciler, "_hd_ccs_own_ports", ())
            loopback = ("127.0.0.1", "localhost", "::1", "0.0.0.0")
            return host in loopback and _hd_ccs_port(url) in own

        def _hd_ccs_points_here(reconciler):
            data = _hd_ccs_json.loads(reconciler.path.read_text(encoding="utf-8"))
            env = data.get("env") if isinstance(data, dict) else None
            url = env.get("ANTHROPIC_BASE_URL") if isinstance(env, dict) else None
            return isinstance(url, str) and url.rstrip("/") == _hd_ccs_url

        _hd_ccs_orig_init = _hd_ccs_mod.CCSwitchReconciler.__init__

        def _hd_ccs_init(self, *args, **kwargs):
            _hd_ccs_orig_init(self, *args, **kwargs)
            ports = {_hd_ccs_port(self.proxy_url), _hd_ccs_port(_hd_ccs_url)}
            self._hd_ccs_own_ports = ports - {None}
            # Already rstripped, which is what the loop guard compares against.
            self.proxy_url = _hd_ccs_url
            _hd_ccs_set = self._set_upstream

            def _hd_ccs_guarded_set(url):
                if _hd_ccs_is_self(self, url):
                    _hd_ccs_log.info("event=cc_switch_self_upstream_ignored url=%s", url)
                    return
                _hd_ccs_set(url)

            self._set_upstream = _hd_ccs_guarded_set

        _hd_ccs_mod.CCSwitchReconciler.__init__ = _hd_ccs_init

        def _hd_ccs_selects_official(reconciler):
            # True when settings.json names no base URL at all -- what cc-switch
            # writes for "Claude Official" ({"env": {}}). Raises on a partial
            # read (caught mid atomic-replace); the caller must not consume the
            # mtime in that case.
            data = _hd_ccs_json.loads(reconciler.path.read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                return False
            env = data.get("env")
            url = env.get("ANTHROPIC_BASE_URL") if isinstance(env, dict) else None
            return not (isinstance(url, str) and url.strip())

        def _hd_ccs_tick(self):
            global _hd_ccs_warned
            if not _hd_os.path.exists(_hd_ccs_routed):
                # Neither capture nor rewrite, and let go of a live capture:
                # nothing routes to it now, and a switch to Official would go
                # unseen. None, so routing again reseeds from the file.
                target = _hd_ccs_pinned or self.default_upstream
                if self.current_upstream not in (None, target):
                    self._set_upstream(target)
                    _hd_ccs_log.info("event=cc_switch_upstream_released upstream=%s", target)
                self.current_upstream = None
                return False
            prev = self.current_upstream
            seen = getattr(self, "_last_mtime_ns", None)
            rewrote = _hd_ccs_orig_tick(self)
            if rewrote:
                # Only a rewrite captures, so this stays off the 0.3s hot path.
                try:
                    if _hd_ccs_is_self(self, self.current_upstream):
                        # settings.json already named us, just spelled another
                        # way; the guarded setter refused it as the upstream.
                        self.current_upstream = prev
                    elif self.current_upstream not in (None, self.default_upstream):
                        # Before the pin below: the file is what settings.json
                        # said, which is what quit restores either way.
                        _hd_ccs_save_capture(self.current_upstream)
                except Exception as exc:  # noqa: BLE001 - the watcher must not die
                    _hd_ccs_log.warning("event=cc_switch_capture_persist_failed err=%s", exc)
            try:
                # Since 0.40.0 (#3166) the wheel's own tick resets a captured
                # third party to the default on a switch to Official, so the
                # reset below never sees it: end the capture here, or a quit
                # restores the relay over Claude Official.
                if prev not in (None, self.default_upstream) and (
                    self.current_upstream == self.default_upstream
                ):
                    _hd_ccs_drop_capture()
                # With an override configured, the user's endpoint IS the
                # default this reconciler returns to -- both when cc-switch
                # captures something else and when it goes back to Official.
                target = _hd_ccs_pinned or self.default_upstream
                if _hd_ccs_pinned:
                    if self.current_upstream != target:
                        self.current_upstream = target
                        self._set_upstream(target)
                        _hd_ccs_log.info(
                            "event=cc_switch_upstream_pinned upstream=%s", target
                        )
                    return rewrote
                # A new instance (relaunch, resume) meeting settings.json that
                # already names us: the desktop, racing this process at launch,
                # routed the provider URL the quit restored before we could
                # capture it. Only on a settings.json change, and only when it
                # points here -- anything else (Claude Official) would send
                # Anthropic OAuth traffic to the recorded provider.
                if (
                    self.current_upstream is None
                    and not rewrote
                    and getattr(self, "_last_mtime_ns", None) != seen
                ):
                    captured = _hd_ccs_load_capture()
                    if captured and not _hd_ccs_is_self(self, captured) and _hd_ccs_points_here(self):
                        self.current_upstream = captured
                        self._set_upstream(captured)
                        _hd_ccs_log.info(
                            "event=cc_switch_capture_restored upstream=%s", captured
                        )
                # Only a captured third-party upstream can go stale, and only a
                # changed settings.json can end it. Both checks keep this off
                # the hot path of a 0.3s poll -- an Anthropic-only user never
                # gets past the first one. On a wheel carrying #3166 (0.41.0)
                # the tick has already reset current_upstream by the time we
                # look, so this reset is the fallback for a wheel without it.
                if self.current_upstream in (None, target):
                    return rewrote
                mtime_ns = self.path.stat().st_mtime_ns
                if mtime_ns == getattr(self, "_hd_ccs_mtime_ns", None):
                    return rewrote
                official = _hd_ccs_selects_official(self)
                # Read succeeded: only now is this mtime processed.
                self._hd_ccs_mtime_ns = mtime_ns
                if official:
                    self.current_upstream = target
                    self._set_upstream(target)
                    _hd_ccs_log.info(
                        "event=cc_switch_official_upstream_reset upstream=%s",
                        target,
                    )
                    _hd_ccs_drop_capture()
            except Exception as exc:  # noqa: BLE001 - the watcher must not die
                # Logged once: the reconciler is running and the reset that
                # makes it safe just did not happen, so a captured third-party
                # endpoint may still be live. Never silent.
                if not _hd_ccs_warned:
                    _hd_ccs_warned = True
                    _hd_ccs_log.warning(
                        "event=cc_switch_official_reset_failed err=%s "
                        "(set HEADROOM_CC_SWITCH_RECONCILE=0 to leave cc-switch alone)",
                        exc,
                    )
            return rewrote

        _hd_ccs_mod.CCSwitchReconciler.tick = _hd_ccs_tick
        _hd_bound.add("cc_switch_reset")
    except Exception:
        # Fail closed: without the reset, a switch back to Claude Official
        # leaves the captured third-party endpoint live process-wide and
        # Anthropic OAuth traffic follows it. Off is always the safe answer for
        # an opt-in flag.
        _hd_os.environ["HEADROOM_CC_SWITCH_RECONCILE"] = "0"




# --- Tool-reference 400: append a "start a new session" hint (vendor) ----------
# When an MCP server disconnects mid-session (Claude Code does not auto-reconnect
# stdio MCP servers), its tools vanish while the transcript still references them,
# and upstream 400s "Tool reference 'X' not found in available tools". The repair
# strips most of these on the wire; for the residual that still reaches the user,
# append a Headroom hint with the actionable remedy (a fresh session re-spawns the
# MCP server). The streaming handler buffers the upstream error via aread() and
# returns a plain Response, so we post-process that Response only: a raw substring
# insert inside the message (valid whether the body is JSON or an SSE error event),
# guarded so it never touches a StreamingResponse, a non-400, or an already-hinted
# body. Fail-open: any error returns the original response untouched.
# Exact-pin gated to wheel 0.41.0. Kill switch: HEADROOM_TOOL_REF_HINT=0.
_hd_hint_flag = _hd_os.environ.get("HEADROOM_TOOL_REF_HINT", "1")
if _hd_hint_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        import importlib.metadata as _hd_hint_meta

        if _hd_hint_meta.version("headroom-ai") == "0.41.0":
            from headroom.proxy.handlers import streaming as _hd_hint_mod

            _hd_hint_sig = b"not found in available tools"
            _hd_hint_add = (
                b"not found in available tools. Headroom: this error is caused by a "
                b"disconnected MCP server. Close this session and start a new one to fix it."
            )
            _hd_hint_orig = _hd_hint_mod.StreamingMixin._stream_response

            def _hd_hint_apply(result):
                # Only a buffered 400 Response carrying the signature; never a
                # StreamingResponse (no .body), never double-hinted.
                body = getattr(result, "body", None)
                if (
                    getattr(result, "status_code", 200) == 400
                    and isinstance(body, (bytes, bytearray))
                    and _hd_hint_sig in body
                    and b"Headroom:" not in body
                ):
                    from starlette.responses import Response as _hd_hint_resp

                    new_body = bytes(body).replace(_hd_hint_sig, _hd_hint_add, 1)
                    headers = dict(result.headers)
                    headers.pop("content-length", None)
                    return _hd_hint_resp(
                        content=new_body,
                        status_code=result.status_code,
                        headers=headers,
                        media_type=getattr(result, "media_type", None),
                    )
                return result

            async def _hd_hint_wrapped(self, *args, **kwargs):
                result = await _hd_hint_orig(self, *args, **kwargs)
                try:
                    return _hd_hint_apply(result)
                except Exception:
                    return result

            _hd_hint_mod.StreamingMixin._stream_response = _hd_hint_wrapped
            _hd_bound.add("tool_ref_hint")
    except Exception:
        # Response-shaping only: on any binding failure the client sees the
        # upstream error verbatim (the pre-vendor behavior), never a new failure.
        pass

# --- Request-log body window: 20, not 100 (desktop setting) -------------------
# With --log-messages (the Activity before/after view) the wheel
# keeps request, compressed and response bodies on its newest
# RequestLogger.MESSAGE_WINDOW (100) entries, each one a whole transcript. The
# desktop copies the two it shows (the large-compression and record tiles) into
# its own memory on the next 20s observer tick, so the backend only has to hold
# them that long. 20, not 10: requests landing before the next tick pushed 6.4%
# of requests out of a 10-entry window before the copy, 0.5% out of 20
# (request-id counters, 526 requests on a heavy machine, 2026-10-01).
# Only ever narrows the wheel's own constant, so it is gated on
# that attribute rather than an exact pin: a wheel without it reports skipped.
# HEADROOM_MESSAGE_WINDOW=0 keeps the wheel's window.
_hd_mw_size = _hd_os.environ.get("HEADROOM_MESSAGE_WINDOW", "20").strip()
if _hd_mw_size.isdigit() and int(_hd_mw_size) > 0:
    try:
        from headroom.proxy import request_logger as _hd_mw_mod

        if int(_hd_mw_size) < getattr(_hd_mw_mod.RequestLogger, "MESSAGE_WINDOW", 0):
            _hd_mw_mod.RequestLogger.MESSAGE_WINDOW = int(_hd_mw_size)
            _hd_bound.add("message_window")
    except Exception:
        # Memory only: the wheel's 100-entry window stands.
        pass

# --- Embedding relevance: 16 texts per ONNX run, not 256 (vendor, upstream owed) -
# The content router's relevance split embeds every record of a tool output in
# one fastembed embed() at its default batch of 256, padded to the longest text.
# fastembed's ONNX session keeps ORT's CPU arena on and the arena never shrinks,
# so it grows to the biggest batch the proxy ever scored: 2.5 GB pinned on a
# 4-day macOS proxy (2026-10-27), out of the periodic trim's reach. 16 retained
# ~10x less and ran faster, with the same keep/drop decisions. Python only: the
# Rust core's scorer never loads its model in 0.41.0. Drop when the wheel has
# `embedding.EMBED_BATCH_SIZE` (upstream PR #4507).
# Concurrent splits still stacked the arena to +2.2 GB, so each run also asks ORT
# to hand its free arena regions back: +80 MB settled after 4 parallel 128-record
# splits, same speed (M6, 2026-10-29). Only under MallocLargeCache=0, which the
# wheel's macOS CLI re-exec sets (#2879): without it libmalloc keeps the freed
# blocks dirty and shrinking re-grew the arena to +3.8 GB. Windows and Linux are
# unmeasured and never set it, so they keep the cap alone.
# Exact-pin gated to wheel 0.41.0. Kill switches: HEADROOM_EMBED_BATCH_CAP=0,
# HEADROOM_EMBED_ARENA_SHRINK=0 (shrinkage only).
_hd_ebc_flag = _hd_os.environ.get("HEADROOM_EMBED_BATCH_CAP", "1")
if _hd_ebc_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        import importlib.metadata as _hd_ebc_meta

        if _hd_ebc_meta.version("headroom-ai") == "0.41.0":
            from headroom.relevance import embedding as _hd_ebc_mod

            _hd_ebc_shrink = (
                _hd_os.environ.get("MallocLargeCache") == "0"
                and _hd_os.environ.get("HEADROOM_EMBED_ARENA_SHRINK", "1").strip().lower()
                not in ("", "0", "false", "no", "off")
            )

            def _hd_ebc_arm(model):
                model._hd_ebc_armed = True
                import onnxruntime as _hd_ebc_ort

                session = model.model.model  # TextEmbedding -> OnnxTextEmbedding -> InferenceSession
                opts = _hd_ebc_ort.RunOptions()
                opts.add_run_config_entry("memory.enable_memory_arena_shrinkage", "cpu:0")
                run = session.run
                session.run = lambda names, feed, run_options=None: run(names, feed, run_options or opts)

            def _hd_ebc_encode(self, texts):
                model = self._get_model()
                if _hd_ebc_shrink and not getattr(model, "_hd_ebc_armed", False):
                    try:
                        _hd_ebc_arm(model)
                    except Exception:
                        pass  # Memory only: the arena keeps its high-water mark.
                return _hd_ebc_mod._get_numpy().array(list(model.embed(texts, batch_size=16)))

            _hd_ebc_mod.EmbeddingScorer._encode = _hd_ebc_encode
            _hd_bound.add("embed_batch_cap")
    except Exception:
        # Memory only: on any binding failure the wheel's batch of 256 stands.
        pass

# --- Read maturation: never inside the provider-cached prefix (vendor) --------
# Maturation swaps a quiet Read for a marker only "while it is outside the
# frozen prefix", but the Anthropic handler hands it the pipeline's freeze
# count, min(provider floor, local compression-cache count), and runs it AFTER
# finalize_turn replayed the provider floor. The local count stops at the first
# tool_result the cache never stored (a Read, which the router excludes), so it
# sits at 2 for a whole Claude Code session and every Read matures inside the
# cached prefix 5 quiet turns later: forwarded bytes change 9 messages back from
# the floor and the tail re-writes (Sentry RUST-DP, prefix_rewrite, 436 users).
# finalize_turn's confirmed_frozen_count is that floor; maturation gets the
# larger of the two, so a cached Read stays verbatim, as the module documents.
# Turns that skip the replay (cold cache, restart) keep the wheel's count.
# Exact-pin gated to wheel 0.41.0 (0.42.0 still passes the clamped count).
# Kill switch: HEADROOM_MATURATION_FLOOR=0.
_hd_mf_flag = _hd_os.environ.get("HEADROOM_MATURATION_FLOOR", "1")
if _hd_mf_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        import contextvars as _hd_mf_cv
        import importlib.metadata as _hd_mf_meta

        if _hd_mf_meta.version("headroom-ai") == "0.41.0":
            from headroom.proxy import session_engine as _hd_mf_se
            from headroom.transforms import read_maturation as _hd_mf_rm

            _hd_mf_floor = _hd_mf_cv.ContextVar("desktop_maturation_floor", default=0)
            _hd_mf_finalize = _hd_mf_se.finalize_turn
            _hd_mf_apply = _hd_mf_rm.ReadMaturationManager.apply

            def _hd_mf_finalize_turn(*args, **kwargs):
                _hd_mf_floor.set(max(int(kwargs.get("confirmed_frozen_count") or 0), 0))
                return _hd_mf_finalize(*args, **kwargs)

            def _hd_mf_apply_floored(self, messages, frozen_message_count=0):
                floor = _hd_mf_floor.get()
                # One replay floor per maturation pass: the request task owns it.
                _hd_mf_floor.set(0)
                return _hd_mf_apply(self, messages,
                                    frozen_message_count=max(frozen_message_count, floor))

            # The handler imports finalize_turn per request, so the module
            # attribute is what it calls.
            _hd_mf_se.finalize_turn = _hd_mf_finalize_turn
            _hd_mf_rm.ReadMaturationManager.apply = _hd_mf_apply_floored
            _hd_bound.add("maturation_floor")
    except Exception:
        # On any binding failure the wheel's maturation stands.
        pass

# Proxied guarded upstreams (desktop posture; upstream #3804 shipped as an
# allowlist): since 0.39.0 the wheel pins caller-supplied upstreams
# (x-headroom-base-url) to the address the SSRF guard judged, and refuses them
# outright on a proxy transport, which resolves the target itself. Grok and
# OpenCode route through that header, and httpx builds proxy transports from the
# macOS/Windows system proxy settings, so every Grok/OpenCode request from a
# corporate network failed with UnpinnableUpstreamError (verified through a
# CONNECT proxy: 0.38.0 reached api.x.ai, 0.39.0 answered 502). #3804 landed in
# 0.40.0 as a per-destination list, HEADROOM_PROXIED_BASE_URLS (no wildcard),
# and HEADROOM_ALLOWED_BASE_URLS flips the guard to allow-only: neither can name
# the arbitrary gateway an OpenCode user configured. With
# HEADROOM_ALLOW_PROXIED_GUARDED_UPSTREAMS=1 (the desktop sets it) a proxy route
# forwards on the guard's name verdict, the 0.38.0 behaviour; direct routes stay
# pinned and internal answers are still refused. No self-neutralization: the
# wheel has no blanket allow to detect, so re-check on each bump whether it grew
# one. Exact-pin gated to wheel 0.41.0.
_hd_pgu_flag = _hd_os.environ.get("HEADROOM_ALLOW_PROXIED_GUARDED_UPSTREAMS", "")
if _hd_pgu_flag.strip().lower() in ("1", "true", "yes", "on"):
    try:
        import importlib.metadata as _hd_pgu_meta

        if _hd_pgu_meta.version("headroom-ai") == "0.41.0":
            from headroom.proxy import upstream_pinning as _hd_pgu_mod

            _hd_pgu_cls = _hd_pgu_mod.GuardedUpstreamRefusingTransport
            _hd_pgu_orig = _hd_pgu_cls.handle_async_request

            async def _hd_pgu_handle(self, request):
                pool = getattr(self._inner, "_pool", None)
                if _hd_pgu_mod._PROXY_POOLS and isinstance(
                    pool, _hd_pgu_mod._PROXY_POOLS
                ):
                    return await self._inner.handle_async_request(request)
                return await _hd_pgu_orig(self, request)

            _hd_pgu_cls.handle_async_request = _hd_pgu_handle
            _hd_bound.add("proxied_guarded_upstreams")
    except Exception:
        # Fail-closed: on any binding failure the wheel keeps refusing.
        pass

# --- Output baseline warm-up (desktop feature, not an upstream fix) -----------
# Output savings are scored against the user's UNSHAPED reply lengths, which the
# desktop seeds once from Claude Code transcripts written before install. An
# install with none (new to Claude Code, Codex-only, coming from Claude Desktop)
# never got a baseline, so its output figure read "measuring" forever: 27% of
# 989 new users on 2026-10-16, 126 of them active 3+ days in their first week.
# While the baseline holds fewer than HEADROOM_OUTPUT_WARMUP replies (default
# 200, mirrored by output_savings::OUTPUT_WARMUP_REPLIES), each NEW conversation
# runs unshaped for its whole life (its system tail never flips mid-way) and its
# replies go into the baseline under their own label, never into the A/B control
# arm, which stays the 3% holdout. From then on the install is scored like a
# seeded one. Every caller imports assign_arm/stratum_label from
# headroom.proxy.output_savings at call time and the recorder reads
# parse_stratum_label from that module's globals, so rebinding both modules
# reaches every path, including the two that carry no conversation label. The
# recorder re-reads the disk baseline on each flush and adopts it whenever it
# differs, which would drop every warm-up sample before it is written, so once
# this process has recorded one it adopts only a larger (re-learned) disk
# baseline. The recorder also writes only every 25th record and never at exit,
# so a backend restarted sooner lost its warm-up replies (the train guest sat at
# 10 after 35 of them, 2026-10-17): each warm-up reply is written until the
# baseline reaches the target. Not a wheel bug, so it never self-neutralizes.
# Exact-pin gated to wheel 0.41.0. Kill switch: HEADROOM_OUTPUT_WARMUP=0.
_hd_ow_flag = _hd_os.environ.get("HEADROOM_OUTPUT_WARMUP", "200").strip().lower()
if _hd_os.environ.get(
    "HEADROOM_SDK"
) == "headroom-desktop-proxy" and _hd_ow_flag not in ("", "0", "false", "no", "off"):
    try:
        import importlib.metadata as _hd_ow_meta

        if _hd_ow_meta.version("headroom-ai") == "0.41.0":
            import contextvars as _hd_ow_cv

            from headroom.proxy import output_savings as _hd_ow_os
            from headroom.proxy import output_savings_policy as _hd_ow_pol

            _hd_ow_target = int(_hd_ow_flag) if _hd_ow_flag.isdigit() else 200
            _HD_OW_LABEL = "output_shaper:warmup:"
            # Conversations started in warm-up. In-process only: after a restart
            # one is judged afresh, and a restart re-writes its cache anyway.
            _hd_ow_convs = set()
            _hd_ow_recorded = [False]
            # Set by assign_arm, read by the stratum_label call that follows it
            # in the same request (no await between the two on any path).
            _hd_ow_req = _hd_ow_cv.ContextVar("hd_output_warmup", default=False)
            _hd_ow_orig_assign = _hd_ow_pol.assign_arm
            _hd_ow_orig_label = _hd_ow_pol.stratum_label
            _hd_ow_orig_parse = _hd_ow_pol.parse_stratum_label
            _hd_ow_orig_record = _hd_ow_os.SavingsLedger.record
            _hd_ow_orig_reload = _hd_ow_os.SavingsRecorder._reload_baseline_locked
            _hd_ow_orig_from_labels = _hd_ow_os.SavingsRecorder.record_from_labels

            def _hd_ow_assign(conversation_key, holdout_fraction):
                warm = conversation_key in _hd_ow_convs
                if not warm and len(_hd_ow_convs) < 10000:
                    baseline = _hd_ow_os.get_recorder()._ledger.baseline
                    if baseline.total_samples < _hd_ow_target:
                        _hd_ow_convs.add(conversation_key)
                        warm = True
                _hd_ow_req.set(warm)
                if warm:
                    return "control"
                return _hd_ow_orig_assign(conversation_key, holdout_fraction)

            def _hd_ow_label(arm, key):
                if arm == "control" and _hd_ow_req.get():
                    return _HD_OW_LABEL + key
                return _hd_ow_orig_label(arm, key)

            def _hd_ow_parse(label):
                if label.startswith(_HD_OW_LABEL):
                    return "warmup", label[len(_HD_OW_LABEL) :]
                return _hd_ow_orig_parse(label)

            def _hd_ow_record(self, arm, key, output_tokens, conversation=None):
                if arm != "warmup":
                    return _hd_ow_orig_record(self, arm, key, output_tokens, conversation)
                self.baseline.observe(key, output_tokens)
                _hd_ow_recorded[0] = True
                return None

            def _hd_ow_reload(self):
                if not _hd_ow_recorded[0]:
                    return _hd_ow_orig_reload(self)
                try:
                    disk = _hd_ow_os.SavingsLedger.load(self._path)
                except OSError:
                    return None
                if disk.baseline.total_samples > self._ledger.baseline.total_samples:
                    self._ledger.baseline = disk.baseline
                return None

            def _hd_ow_from_labels(self, labels, output_tokens):
                labels = tuple(labels or ())
                recorded = _hd_ow_orig_from_labels(self, labels, output_tokens)
                if (
                    recorded
                    and self._ledger.baseline.total_samples <= _hd_ow_target
                    and any(str(label).startswith(_HD_OW_LABEL) for label in labels)
                ):
                    self.flush()
                return recorded

            for _hd_ow_mod in (_hd_ow_pol, _hd_ow_os):
                _hd_ow_mod.assign_arm = _hd_ow_assign
                _hd_ow_mod.stratum_label = _hd_ow_label
                _hd_ow_mod.parse_stratum_label = _hd_ow_parse
            _hd_ow_os.SavingsLedger.record = _hd_ow_record
            _hd_ow_os.SavingsRecorder._reload_baseline_locked = _hd_ow_reload
            _hd_ow_os.SavingsRecorder.record_from_labels = _hd_ow_from_labels
            _hd_bound.add("output_warmup")
    except Exception:
        pass

# --- Learn: non-string rule fields from the model (vendor, upstream PR #2471) --
# The learn prompt asks for each rule's content as "1-3 bullet points", and a
# model that returns them as a JSON array killed the whole analysis: the wheel's
# _parse_llm_response (0.39.0 through 0.41.0) calls .strip() on section/content
# unchecked ("'list' object has no attribute 'strip'", RUST-K5). Normalize first: a list of strings
# becomes bullet lines (kept, where #2471 drops it), any other non-string
# becomes "" so the parser skips that rule, and a null rules list reads as
# empty. The desktop puts this file on the learn subprocess's PYTHONPATH too.
# Exact-pin gated to wheel 0.41.0; self-neutralizes once the wheel carries
# #2471's `_as_str`. Kill switch: HEADROOM_LEARN_RULE_COERCE=0.
_hd_lrc_flag = _hd_os.environ.get("HEADROOM_LEARN_RULE_COERCE", "1")
if _hd_lrc_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        import importlib.metadata as _hd_lrc_meta

        if _hd_lrc_meta.version("headroom-ai") == "0.41.0":
            from headroom.learn import analyzer as _hd_lrc_mod

            if not hasattr(_hd_lrc_mod, "_as_str"):
                _hd_lrc_orig = _hd_lrc_mod._parse_llm_response

                def _hd_lrc_text(val):
                    if isinstance(val, list) and all(isinstance(v, str) for v in val):
                        return "\n".join(
                            v if v.lstrip().startswith(("-", "*")) else f"- {v}"
                            for v in val
                        )
                    return val if isinstance(val, str) else ""

                def _hd_lrc_parse(raw):
                    if isinstance(raw, dict):
                        raw = dict(raw)
                        for key in ("context_file_rules", "memory_file_rules"):
                            raw[key] = [
                                {
                                    **r,
                                    "section": r.get("section")
                                    if isinstance(r.get("section"), str)
                                    else "",
                                    "content": _hd_lrc_text(r.get("content")),
                                }
                                if isinstance(r, dict)
                                else r
                                for r in (raw.get(key) or [])
                            ]
                    return _hd_lrc_orig(raw)

                _hd_lrc_mod._parse_llm_response = _hd_lrc_parse
                _hd_bound.add("learn_rule_coerce")
    except Exception:
        pass

# --- Learn: a rescan sees the block the last scan wrote (vendor, upstream owed) -
# ClaudeCodeWriter writes a project's learned block to CLAUDE.local.md (the home
# project's to ~/.claude/CLAUDE.md), but discover_projects points context_file,
# the file _build_prior_patterns_section shows the model beside MEMORY.md, at
# CLAUDE.md. So every rescan started from nothing, named its sections afresh (in
# the sessions' language: Spanish one run, English the next), and
# _merge_recommendations kept every old section whose heading was not reused
# verbatim: duplicate sections piling up in ten projects (a customer,
# 2026-10-18). context_file now names the writer's file whenever it holds the
# block, and the prompt asks for a prior heading to be reused as written.
# ClaudeCodeWriter ignores context_file, so only the analysis input changes.
# The wheel merges worktrees itself (#3854), so merged projects are covered.
# Exact-pin gated to wheel 0.41.0; self-neutralizes once the plugin or the
# analyzer names CLAUDE.local.md. Kill switch: HEADROOM_LEARN_PRIOR_LOCAL=0.
_hd_lpl_flag = _hd_os.environ.get("HEADROOM_LEARN_PRIOR_LOCAL", "1")
if _hd_lpl_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        import importlib.metadata as _hd_lpl_meta

        if _hd_lpl_meta.version("headroom-ai") == "0.41.0":
            import inspect as _hd_lpl_inspect
            from pathlib import Path as _hd_lpl_Path

            from headroom.learn import analyzer as _hd_lpl_an
            from headroom.learn import writer as _hd_lpl_wr
            from headroom.learn.plugins import claude as _hd_lpl_mod

            if not any(
                "CLAUDE.local.md" in _hd_lpl_inspect.getsource(m)
                for m in (_hd_lpl_mod, _hd_lpl_an)
            ):
                _hd_lpl_cls = _hd_lpl_mod.ClaudeCodePlugin
                _hd_lpl_discover = _hd_lpl_cls.discover_projects
                _hd_lpl_anchor = "- Sections from prior runs that you do NOT re-emit"

                def _hd_lpl_discover_projects(self):
                    projects = _hd_lpl_discover(self)
                    for p in projects:
                        # Where ClaudeCodeWriter._resolve_context_path writes
                        # without --target. In place: a merged worktree project
                        # carries attributes dataclasses.replace would drop.
                        if p.project_path == _hd_lpl_Path.home():
                            target = _hd_lpl_wr.claude_config_dir() / "CLAUDE.md"
                        else:
                            target = p.project_path / "CLAUDE.local.md"
                        try:
                            text = target.read_text(encoding="utf-8", errors="replace")
                        except Exception:
                            continue
                        if _hd_lpl_wr.extract_marker_block(text):
                            p.context_file = target
                    return projects

                if _hd_lpl_anchor in _hd_lpl_an._SYSTEM_PROMPT:
                    _hd_lpl_an._SYSTEM_PROMPT = _hd_lpl_an._SYSTEM_PROMPT.replace(
                        _hd_lpl_anchor,
                        "- A section on a topic the prior block already has a heading\n"
                        "  for reuses that heading exactly as written, in its language,\n"
                        "  so it replaces the prior section instead of sitting beside it.\n"
                        + _hd_lpl_anchor,
                        1,
                    )
                _hd_lpl_cls.discover_projects = _hd_lpl_discover_projects
                _hd_bound.add("learn_prior_local")
    except Exception:
        pass

# --- Learn: the learned block stays under a size budget (posture) -------------
# _merge_recommendations carries every prior section a rescan does not re-emit,
# forever, so a project's learned block only grows, and Claude Code re-sends it
# with every request in that project. One machine reached 14 sections (five of
# them renamed duplicates) and ~3.2k tokens a request (2026-10-19). Past the
# budget (chars of the rendered block) the carried sections go, least
# estimated_tokens_saved first; the run's own sections always stay. Not
# version-gated: a wheel without the function leaves this inert. Kill switch:
# HEADROOM_LEARN_BLOCK_CAP=0; any other number is the budget.
try:
    _hd_lbc_budget = int(_hd_os.environ.get("HEADROOM_LEARN_BLOCK_CAP", "6000"))
except ValueError:
    _hd_lbc_budget = 6000
if _hd_lbc_budget > 0:
    try:
        from headroom.learn import writer as _hd_lbc_wr

        _hd_lbc_merge = _hd_lbc_wr._merge_recommendations
        _hd_lbc_build = _hd_lbc_wr._build_section

        def _hd_lbc_merge_capped(file_path, new_recommendations, *args, **kwargs):
            merged = _hd_lbc_merge(file_path, new_recommendations, *args, **kwargs)
            if len(_hd_lbc_build(merged)) <= _hd_lbc_budget:
                return merged
            fresh = {r.section for r in new_recommendations}
            carried = [r for r in merged if r.section not in fresh]
            drop = set()
            for r in sorted(carried, key=lambda r: r.estimated_tokens_saved):
                drop.add(id(r))
                kept = [m for m in merged if id(m) not in drop]
                if len(_hd_lbc_build(kept)) <= _hd_lbc_budget:
                    return kept
            return [m for m in merged if id(m) not in drop]

        _hd_lbc_wr._merge_recommendations = _hd_lbc_merge_capped
        _hd_bound.add("learn_block_cap")
    except Exception:
        pass

# --- Traffic learner: no error-recovery section in MEMORY.md (posture) ---------
# The recommendation builder skips any category missing from this routing table,
# so dropping ERROR_RECOVERY stops the section at the source. Not version-gated:
# a wheel that renames the table just leaves this inert. Kill switch:
# HEADROOM_LEARN_DROP_ERROR_RECOVERY=0.
_hd_ler_flag = _hd_os.environ.get("HEADROOM_LEARN_DROP_ERROR_RECOVERY", "1")
if _hd_ler_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        from headroom.memory import traffic_learner as _hd_ler_mod

        _hd_ler_mod._CATEGORY_TO_TARGET.pop(_hd_ler_mod.PatternCategory.ERROR_RECOVERY, None)
        _hd_bound.add("learn_drop_error_recovery")
    except Exception:
        pass

# --- Learn: `codex exec` gives up on a dead route (posture) --------------------
# Codex ships `unbounded_connection_retries` on (0.156.1 and the ChatGPT app's
# 0.160.0 both do): when it cannot connect to its provider it prints
# "Reconnecting... waiting for network" and never exits. The analyzer runs
# `codex exec` under a wall clock only and drops its output on timeout, so the
# scan sat out the full 900s and reported only "did not respond within 900s"
# (RUST-P2). Bounded, the same dead route ends in ~25s with codex's own
# "Connection failed" line. `-c`, not `--disable`: an older codex refuses an
# unknown `--disable` name but ignores an unknown config key. Not
# version-gated: a wheel that passes the override itself is left alone. Kill
# switch: HEADROOM_LEARN_CODEX_RETRIES=0.
_hd_lcr_flag = _hd_os.environ.get("HEADROOM_LEARN_CODEX_RETRIES", "1")
if _hd_lcr_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        from headroom.learn import analyzer as _hd_lcr_mod

        _hd_lcr_arg = "features.unbounded_connection_retries=false"
        for _hd_lcr_name, _hd_lcr_model, _hd_lcr_cmd in _hd_lcr_mod._CLI_BACKENDS:
            if _hd_lcr_model == "codex-cli" and _hd_lcr_arg not in _hd_lcr_cmd:
                _hd_lcr_cmd.extend(["-c", _hd_lcr_arg])
                _hd_bound.add("learn_codex_retries")
    except Exception:
        pass

# --- Learn: a crashed CLI's padding does not push out its error (diagnostics) --
# Claude Code is a Bun binary, and Bun prints a crash as a source excerpt whose
# caret line is padded out to the failing column, ahead of the error itself.
# The analyzer keeps only the first 2000 chars of a failed CLI's stderr and the
# padding filled them: Claude Code dying in fs.watch reported the excerpt and
# never the errno (RUST-M8, macOS, 0.9.30 and 0.9.40). Runs of 64+ blanks are
# squeezed to one before the cut, in the prompt too: since 0.41.0 the wheel
# drops a prompt the CLI echoed to stderr by matching it there (#3928). Not
# version-gated: stderr without such a run passes through unchanged. Kill
# switch: HEADROOM_LEARN_STDERR_SQUEEZE=0.
_hd_lsq_flag = _hd_os.environ.get("HEADROOM_LEARN_STDERR_SQUEEZE", "1")
if _hd_lsq_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        import re as _hd_lsq_re
        from headroom.learn import analyzer as _hd_lsq_mod

        _hd_lsq_orig = _hd_lsq_mod._failure_detail
        _hd_lsq_pad = _hd_lsq_re.compile(r"[ \t]{64,}")

        def _hd_lsq_detail(stderr, *args, **kwargs):
            if isinstance(stderr, str):
                stderr = _hd_lsq_pad.sub(" ", stderr)
            # Squeezed alike, or the wheel's echo strip (`echo in stderr`)
            # misses a prompt with a long blank run and the prompt leaks
            # into the error (RUST-KT).
            if isinstance(kwargs.get("prompt"), str):
                kwargs["prompt"] = _hd_lsq_pad.sub(" ", kwargs["prompt"])
            return _hd_lsq_orig(stderr, *args, **kwargs)

        _hd_lsq_mod._failure_detail = _hd_lsq_detail
        _hd_bound.add("learn_stderr_squeeze")
    except Exception:
        pass

# --- Learn: a CLI that exits before reading the prompt says why (diagnostics) --
# The claude-cli path writes the whole prompt to the child's stdin before it
# starts reading the child's output, so a CLI that exits first (an old CLI
# refusing a flag, a shim cmd.exe could not start) fails that write: EINVAL on
# Windows, BrokenPipeError elsewhere. The analysis then reported only
# "[Errno 22] Invalid argument", with the CLI's own stderr and exit code never
# read (RUST-MZ, 0.7s into every run on one Windows machine). A write to a
# child that is already gone is dropped instead, so the analyzer reads the exit
# and reports the CLI's own error. Not version-gated: a wheel that stops
# writing this way leaves nothing to catch. Kill switch:
# HEADROOM_LEARN_STDIN_EARLY_EXIT=0.
_hd_lse_flag = _hd_os.environ.get("HEADROOM_LEARN_STDIN_EARLY_EXIT", "1")
if _hd_lse_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        from headroom.learn import analyzer as _hd_lse_mod

        _hd_lse_orig = _hd_lse_mod.Popen

        class _hd_lse_stdin:
            def __init__(self, raw):
                self._raw = raw

            def write(self, data):
                try:
                    return self._raw.write(data)
                except OSError:
                    return 0

            def close(self):
                try:
                    self._raw.close()
                except OSError:
                    pass

            def __getattr__(self, name):
                return getattr(self._raw, name)

        def _hd_lse_popen(*args, **kwargs):
            proc = _hd_lse_orig(*args, **kwargs)
            if proc.stdin is not None:
                proc.stdin = _hd_lse_stdin(proc.stdin)
            return proc

        _hd_lse_mod.Popen = _hd_lse_popen
        _hd_bound.add("learn_stdin_early_exit")
    except Exception:
        pass

# --- Learn: the digest's loop section fits its budget (vendor, upstream owed) --
# _build_digest budgets the per-session event stream but renders every detected
# loop ahead of it, each with every message index it repeated at. Codex learn is
# one project holding every session the machine ever ran, so on a heavy user the
# loops alone outgrew the digest and Codex refused every scan's 1.79M-char prompt
# over its 1,048,576-char input cap (RUST-QV). Only the costliest
# max_tokens // 400 loops are rendered (detect_loops sorts by waste), each with
# its first 20 indices beside its count: under a quarter of the digest budget,
# halving with it on the prompt-too-long retry. Loop weighting still sees every
# loop. Exact-pin gated to wheel 0.41.0. Kill switch: HEADROOM_LEARN_LOOP_BUDGET=0.
_hd_llb_flag = _hd_os.environ.get("HEADROOM_LEARN_LOOP_BUDGET", "1")
if _hd_llb_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        import dataclasses as _hd_llb_dc
        import importlib.metadata as _hd_llb_meta

        if _hd_llb_meta.version("headroom-ai") == "0.41.0":
            from headroom.learn import analyzer as _hd_llb_mod

            _hd_llb_orig = _hd_llb_mod._build_digest

            def _hd_llb_digest(
                project, sessions, loops=None, max_tokens=_hd_llb_mod._MAX_DIGEST_TOKENS
            ):
                if loops is None:
                    loops = _hd_llb_mod.detect_loops(sessions)
                loops = [
                    _hd_llb_dc.replace(lp, msg_indices=lp.msg_indices[:20])
                    for lp in loops[: max_tokens // 400]
                ]
                return _hd_llb_orig(project, sessions, loops=loops, max_tokens=max_tokens)

            _hd_llb_mod._build_digest = _hd_llb_digest
            _hd_bound.add("learn_loop_budget")
    except Exception:
        pass

# --- Learn: OpenCode's v2 session tables (vendor, upstream owed) --------------
# OpenCode moved sessions from session/message/part to session_v2 and
# session_message (tool calls inside each row's data.content), and a database a
# current OpenCode created has no `session` table at all. The wheel's plugin
# (0.41.0) reads only v1, so every learn scan there died on "no such table:
# session" (RUST-HJ, 6 hosts). On a v2 database the plugin's connection gets
# TEMP views with the v1 names and shape, so its own queries and parsing run
# unchanged; TEMP objects never touch the user's file, and a v1 database gets
# none. The part view inverts OpenCode's own v1 -> v2 migration (migrateTool:
# callID -> id, tool -> name, output -> content text, error -> error.message).
# On Windows v2 stores C:/x while the plugin matches str(Path(worktree)), C:\x.
# Exact-pin gated to wheel 0.41.0; self-neutralizes once the plugin names
# session_v2. Kill switch: HEADROOM_LEARN_OPENCODE_V2=0.
_hd_oc2_flag = _hd_os.environ.get("HEADROOM_LEARN_OPENCODE_V2", "1")
if _hd_oc2_flag.strip().lower() not in ("", "0", "false", "no", "off"):
    try:
        import importlib.metadata as _hd_oc2_meta

        if _hd_oc2_meta.version("headroom-ai") == "0.41.0":
            import inspect as _hd_oc2_inspect
            import sqlite3 as _hd_oc2_sqlite
            import types as _hd_oc2_types

            from headroom.learn.plugins import opencode as _hd_oc2_mod

            if "session_v2" not in _hd_oc2_inspect.getsource(_hd_oc2_mod):
                _hd_oc2_worktree = (
                    "replace(worktree, '/', '\\')" if _hd_os.name == "nt" else "worktree"
                )
                _HD_OC2_VIEWS = (
                    "CREATE TEMP VIEW project AS SELECT id, name, "
                    + _hd_oc2_worktree
                    + " AS worktree FROM main.project",
                    "CREATE TEMP VIEW session AS"
                    " SELECT id, project_id, time_created FROM main.session_v2",
                    "CREATE TEMP VIEW message AS SELECT id, session_id FROM main.session_message",
                    "CREATE TEMP VIEW part AS"
                    " SELECT m.id AS message_id,"
                    "  json_object('type', 'tool', 'tool', t.value ->> '$.name',"
                    "   'callID', t.value ->> '$.id',"
                    "   'state', json_object('status', t.value ->> '$.state.status',"
                    "    'input', t.value -> '$.state.input',"
                    "    'output', coalesce(t.value ->> '$.state.error.message',"
                    "     (SELECT group_concat(c.value ->> '$.text', char(10))"
                    "      FROM json_each(t.value, '$.state.content') c"
                    "      WHERE c.value ->> '$.type' = 'text'), ''))) AS data,"
                    "  coalesce(t.value ->> '$.time.created', m.time_created) AS time_created"
                    " FROM main.session_message m, json_each(m.data, '$.content') t"
                    " WHERE t.value ->> '$.type' = 'tool'",
                )

                def _hd_oc2_connect(*args, **kwargs):
                    conn = _hd_oc2_sqlite.connect(*args, **kwargs)
                    try:
                        tables = {
                            r[0]
                            for r in conn.execute(
                                "SELECT name FROM main.sqlite_master WHERE type = 'table'"
                            )
                        }
                        if "session" not in tables and {
                            "project",
                            "session_v2",
                            "session_message",
                        } <= tables:
                            for stmt in _HD_OC2_VIEWS:
                                conn.execute(stmt)
                    except _hd_oc2_sqlite.Error:
                        pass
                    return conn

                _hd_oc2_shim = _hd_oc2_types.ModuleType("sqlite3")
                _hd_oc2_shim.__dict__.update(_hd_oc2_sqlite.__dict__)
                _hd_oc2_shim.connect = _hd_oc2_connect
                _hd_oc2_mod.sqlite3 = _hd_oc2_shim
                _hd_bound.add("learn_opencode_v2")
    except Exception:
        pass

# --- web_search_call history on a request without a web_search tool ----------
# Codex compacts locally for a custom provider such as Headroom's: it resends
# the whole history with `tools: []` and asks for a summary. When that history
# holds a hosted `web_search_call` item, the ChatGPT backend answers 200 and
# then the in-band error "response protection is unavailable". Codex ignores
# in-band `error` events, sees the stream end ("stream closed before
# response.completed"), retries the same body five times, and runs the same
# compaction before every later prompt, so the session never answers again.
# Measured 2026-10-08 straight against chatgpt.com, no Headroom in the path: a
# captured compaction request failed as sent and completed with its 10
# web_search_call items dropped; a normal turn on the same history (which
# declares the tool) is unaffected. Codex on the built-in OpenAI provider uses
# remote compaction instead, so only users of a custom provider hit it. The
# vendor drops web_search_call items from a Responses `input` whose `tools`
# declare no web_search tool, where every forwarder picks its outbound bytes,
# and marks the body mutated so the edit is sent. Only the search action (query
# or URL) leaves the history; its results were never in it. Exact-pin gated to
# wheel 0.41.0; a no-op on any body without such items.
# Kill switch: HEADROOM_WEB_SEARCH_HISTORY=0.
_hd_wsh_flag = _hd_os.environ.get("HEADROOM_WEB_SEARCH_HISTORY", "1")
if _hd_os.environ.get("HEADROOM_SDK") == "headroom-desktop-proxy" and (
    _hd_wsh_flag.strip().lower() not in ("", "0", "false", "no", "off")
):
    try:
        import importlib.metadata as _hd_wsh_meta

        if _hd_wsh_meta.version("headroom-ai") == "0.41.0":
            import logging as _hd_wsh_logging

            from headroom.proxy import body_forwarding as _hd_wsh_mod

            _hd_wsh_orig = _hd_wsh_mod.select_outbound_body
            _hd_wsh_log = _hd_wsh_logging.getLogger("headroom.proxy")

            def _hd_wsh_strip(body):
                items = body.get("input") if isinstance(body, dict) else None
                if not isinstance(items, list):
                    return 0
                tools = body.get("tools")
                if isinstance(tools, list) and any(
                    isinstance(t, dict) and str(t.get("type") or "").startswith("web_search")
                    for t in tools
                ):
                    return 0
                kept = [
                    i
                    for i in items
                    if not (isinstance(i, dict) and i.get("type") == "web_search_call")
                ]
                if len(kept) == len(items):
                    return 0
                body["input"] = kept
                return len(items) - len(kept)

            def _hd_wsh_select(*, body, original_body_bytes, body_mutated, **kwargs):
                dropped = _hd_wsh_strip(body)
                if dropped:
                    body_mutated = True
                    _hd_wsh_log.info(
                        "event=web_search_history dropped=%d (no web_search tool declared)",
                        dropped,
                    )
                return _hd_wsh_orig(
                    body=body,
                    original_body_bytes=original_body_bytes,
                    body_mutated=body_mutated,
                    **kwargs,
                )

            _hd_wsh_mod.select_outbound_body = _hd_wsh_select
            _hd_bound.add("web_search_history")
    except Exception:
        # Fail-open to the wheel's forwarding (the pre-vendor behaviour).
        pass

# --- Buffered CCR turns stream from upstream ----------------------------------
# A streaming Claude Code turn with headroom_retrieve resident is flipped to
# stream:false so the proxy can serve a retrieval server-side. Anthropic then
# sends nothing until the whole reply is generated, and a network middlebox that
# drops HTTP connections idle for 60s (TLS-inspecting antivirus, VPN, corporate
# proxy; TCP keepalive does not reset an L7 idle timer) closes it first: httpx
# raises "Server disconnected without sending a response" at ~60s, the retry
# loop tries three times and Claude Code gets a 502 after ~186s, then resends
# the same body, forever (AppSumo customer 2026-10-08, 1.3-2.9MB opus turns and
# 200KB subagent turns alike; without Headroom the client streams and works).
# The vendor sends that one request as stream:true and folds the SSE reply back
# into the Message JSON the buffered path expects, so bytes (deltas, pings)
# flow the whole time and nothing downstream changes. It applies only to
# api.anthropic.com /v1/messages bodies Headroom serializes itself: the
# buffered flip, or a continuation built from scratch. A client's own
# stream:false bytes stay byte-faithful. The CCR continuation that serves the
# retrieval is a third stream:false call (its own http_client.post, not
# _retry_request) and dropped the same way: 5 a day on one VPN machine at
# 61-66s, 3 of them handing Claude Code a bare headroom_retrieve (rc.8,
# 2026-10-12). Its outbound log line marks it, and the next post in that task
# streams and folds the same way. Request content is unchanged apart from
# the stream flag, so no compression or cache effect. A stream that ends
# without message_stop raises like a dropped connection (the wheel's 502); an
# in-band error event returns its status (529 overloaded, 429, else 500).
# Exact-pin gated to wheel 0.41.0; stands down when the wheel stops flipping.
# Kill switch: HEADROOM_BUFFERED_UPSTREAM_STREAM=0.
_hd_bus_flag = _hd_os.environ.get("HEADROOM_BUFFERED_UPSTREAM_STREAM", "1")
if _hd_os.environ.get("HEADROOM_SDK") == "headroom-desktop-proxy" and (
    _hd_bus_flag.strip().lower() not in ("", "0", "false", "no", "off")
):
    try:
        import importlib.metadata as _hd_bus_meta

        if _hd_bus_meta.version("headroom-ai") == "0.41.0":
            import json as _hd_bus_json
            import logging as _hd_bus_logging
            from urllib.parse import urlsplit as _hd_bus_urlsplit

            import httpx as _hd_bus_httpx
            from headroom.proxy import server as _hd_bus_server
            from headroom.proxy.handlers import anthropic as _hd_bus_anth

            _hd_bus_log = _hd_bus_logging.getLogger("headroom.proxy")
            _hd_bus_orig = _hd_bus_server.HeadroomProxy._retry_request
            _hd_bus_flip = "ccr_streaming_retrieve_buffered_non_stream"
            _hd_bus_status = {"overloaded_error": 529, "rate_limit_error": 429}
            _hd_bus_block_members = {
                "thinking": ("type", "thinking", "signature"),
                "redacted_thinking": ("type", "data"),
            }

            def _hd_bus_applies(method, url, body, kwargs):
                if method != "POST" or not isinstance(body, dict):
                    return False
                if body.get("stream") is not False:
                    return False
                parts = _hd_bus_urlsplit(url)
                if parts.hostname != "api.anthropic.com" or not parts.path.endswith(
                    "/v1/messages"
                ):
                    return False
                if _hd_bus_flip in (kwargs.get("mutation_reasons") or []):
                    return True
                return kwargs.get("original_body_bytes") is None

            def _hd_bus_events(text):
                for chunk in text.replace("\r\n", "\n").split("\n\n"):
                    data = [
                        line[5:].lstrip() for line in chunk.split("\n") if line.startswith("data:")
                    ]
                    if data:
                        yield _hd_bus_json.loads("\n".join(data))

            # The fold mirrors the Anthropic SDK's stream accumulator, the one
            # Claude Code builds a streamed reply with (MessageStream in its
            # bundled @anthropic-ai/sdk): each delta type it knows, and
            # message_delta usage only where non-null. A delta type it does not
            # know raises, so the caller sends the wheel's stream:false request
            # instead of guessing at what that delta means.
            def _hd_bus_fold(text):
                msg, blocks, partial, done = None, {}, {}, False
                for ev in _hd_bus_events(text):
                    kind = ev.get("type")
                    if kind == "error":
                        return None, ev
                    if kind == "message_start":
                        msg = dict(ev["message"])
                        msg["usage"] = dict(msg.get("usage") or {})
                    elif kind == "content_block_start":
                        block = dict(ev["content_block"])
                        blocks[ev["index"]] = block
                        if block.get("type") == "fallback" and msg is not None:
                            msg["model"] = block["to"]["model"]
                    elif kind == "content_block_delta":
                        index, delta = ev["index"], ev["delta"]
                        block, dtype = blocks[index], delta["type"]
                        if dtype == "text_delta":
                            block["text"] = (block.get("text") or "") + delta["text"]
                        elif dtype == "citations_delta":
                            block["citations"] = (block.get("citations") or []) + [delta["citation"]]
                        elif dtype == "input_json_delta":
                            partial[index] = partial.get(index, "") + delta["partial_json"]
                        elif dtype == "thinking_delta":
                            # Not its estimated_tokens: a progress count the
                            # Message schema lacks (rc.1 resent it: 400).
                            block["thinking"] = (block.get("thinking") or "") + delta["thinking"]
                        elif dtype == "signature_delta":
                            block["signature"] = delta["signature"]
                        elif dtype == "compaction_delta":
                            block["content"] = delta.get("content")
                            if "encrypted_content" in delta:
                                block["encrypted_content"] = delta["encrypted_content"]
                        else:
                            raise ValueError("unknown delta type %r" % (dtype,))
                    elif kind == "content_block_stop":
                        raw = partial.pop(ev["index"], None)
                        if raw is not None:
                            blocks[ev["index"]]["input"] = (
                                _hd_bus_json.loads(raw) if raw.strip() else {}
                            )
                    elif kind == "message_delta" and msg is not None:
                        msg.update(ev.get("delta") or {})
                        msg["usage"].update(
                            (k, v) for k, v in (ev.get("usage") or {}).items() if v is not None
                        )
                        for key, value in ev.items():
                            if key not in ("type", "delta", "usage") and value is not None:
                                msg[key] = value
                    elif kind == "message_stop":
                        done = True
                if msg is None or not done:
                    return None, None
                # The stream adds placeholders the Message schema lacks (a thinking
                # block's estimated_tokens: null); the CCR continuation resends this
                # content as is and Anthropic 400s "Extra inputs are not permitted"
                # on any of them. A null member carries no content, so it leaves
                # every block type; thinking blocks keep only their schema.
                content = []
                for i in sorted(blocks):
                    block = {k: v for k, v in blocks[i].items() if v is not None}
                    keep = _hd_bus_block_members.get(block.get("type"))
                    if keep:
                        block = {k: v for k, v in block.items() if k in keep}
                    content.append(block)
                msg["content"] = content
                return msg, None

            def _hd_bus_reply(resp, status, payload):
                headers = [
                    (k, v)
                    for k, v in resp.headers.items()
                    if k.lower()
                    not in ("content-type", "content-length", "content-encoding", "transfer-encoding")
                ]
                headers.append(("content-type", "application/json"))
                return _hd_bus_httpx.Response(
                    status,
                    headers=headers,
                    content=_hd_bus_json.dumps(payload, ensure_ascii=False).encode(),
                    request=resp.request,
                )

            def _hd_bus_sse_headers(headers):
                sse_headers = {k: v for k, v in (headers or {}).items() if k.lower() != "accept"}
                sse_headers["accept"] = "text/event-stream"
                return sse_headers

            async def _hd_bus_retry_request(self, method, url, headers, body, stream=False, **kwargs):
                if stream or not _hd_bus_applies(method, url, body, kwargs):
                    return await _hd_bus_orig(self, method, url, headers, body, stream, **kwargs)
                sse_kwargs = {
                    **kwargs,
                    "body_mutated": True,
                    "mutation_reasons": list(kwargs.get("mutation_reasons") or [])
                    + ["buffered_upstream_stream"],
                }
                resp = await _hd_bus_orig(
                    self,
                    method,
                    url,
                    _hd_bus_sse_headers(headers),
                    {**body, "stream": True},
                    False,
                    **sse_kwargs,
                )
                return await _hd_bus_settle(
                    resp, lambda: _hd_bus_orig(self, method, url, headers, body, stream, **kwargs)
                )

            async def _hd_bus_settle(resp, fallback):
                if resp.status_code != 200 or "text/event-stream" not in resp.headers.get(
                    "content-type", ""
                ):
                    # An HTTP error, or the client's own bytes went out (signed
                    # thinking): either way the reply is already what the caller reads.
                    return resp
                try:
                    msg, err = _hd_bus_fold(resp.text)
                except Exception as exc:
                    # A reply this fold cannot read would 502 the same way on every
                    # resend; the wheel's own stream:false request answers it (one
                    # more generation, the pre-vendor path).
                    _hd_bus_log.warning(
                        "event=buffered_upstream_stream fold_failed=%s", type(exc).__name__
                    )
                    return await fallback()
                if err is not None:
                    etype = (err.get("error") or {}).get("type")
                    _hd_bus_log.warning("event=buffered_upstream_stream in_band_error=%s", etype)
                    return _hd_bus_reply(resp, _hd_bus_status.get(etype, 500), err)
                if msg is None:
                    raise _hd_bus_httpx.RemoteProtocolError(
                        "upstream stream ended before message_stop", request=resp.request
                    )
                return _hd_bus_reply(resp, 200, msg)

            # The CCR continuation: its api_call_fn imports log_outbound_request
            # at call time and posts right after it, in the same task, so the
            # mark is read by exactly that post and cleared there.
            import contextvars as _hd_bus_cv

            from headroom.proxy import body_forwarding as _hd_bus_bf
            from headroom.proxy import helpers as _hd_bus_helpers

            _hd_bus_cont = _hd_bus_cv.ContextVar("_hd_bus_cont", default=False)
            _hd_bus_log_orig = _hd_bus_helpers.log_outbound_request
            _hd_bus_post_orig = _hd_bus_httpx.AsyncClient.post

            def _hd_bus_log_outbound(**kwargs):
                if kwargs.get("forwarder") == "anthropic_ccr_continuation":
                    _hd_bus_cont.set(True)
                return _hd_bus_log_orig(**kwargs)

            async def _hd_bus_post(self, url, **kwargs):
                if not _hd_bus_cont.get():
                    return await _hd_bus_post_orig(self, url, **kwargs)
                _hd_bus_cont.set(False)
                try:
                    body = _hd_bus_json.loads(kwargs.get("content") or b"")
                except ValueError:
                    body = None
                if not _hd_bus_applies("POST", str(url), body, {}):
                    return await _hd_bus_post_orig(self, url, **kwargs)
                content, _ = _hd_bus_bf.prepare_outbound_body_bytes(
                    body={**body, "stream": True}, original_body_bytes=None, body_mutated=True
                )
                _hd_bus_log.info("event=buffered_upstream_stream forwarder=anthropic_ccr_continuation")
                resp = await _hd_bus_post_orig(
                    self,
                    url,
                    **{**kwargs, "content": content, "headers": _hd_bus_sse_headers(kwargs.get("headers"))},
                )
                return await _hd_bus_settle(resp, lambda: _hd_bus_post_orig(self, url, **kwargs))

            with open(_hd_bus_anth.__file__, encoding="utf-8") as _hd_bus_src:
                _hd_bus_text = _hd_bus_src.read()
            if _hd_bus_flip in _hd_bus_text:
                _hd_bus_server.HeadroomProxy._retry_request = _hd_bus_retry_request
                if 'forwarder="anthropic_ccr_continuation"' in _hd_bus_text:
                    _hd_bus_helpers.log_outbound_request = _hd_bus_log_outbound
                    _hd_bus_httpx.AsyncClient.post = _hd_bus_post
                _hd_bound.add("buffered_upstream_stream")
    except Exception:
        # Fail-open to the wheel's buffered stream:false request.
        pass

# --- Prefix tracker: a deferred tool load is not a new conversation -----------
# The tracker lineage is keyed on a fingerprint of the cache-key segments
# before the messages, the whole `tools` array included. Claude Code appends
# every tool ToolSearch loads to `tools`, still marked defer_loading, and
# Anthropic leaves deferred tools out of the cached prompt (a direct session
# keeps reading its cache across the load). The proxy saw a new conversation:
# a fresh tracker, frozen=0, and the whole history re-run through the
# pipeline, whose output differs from the bytes already cached (reads that
# were recent then and are older now, a background Kompress result), so the
# message tier was re-written. On one machine over 5 days, the turn after a
# deferred load missed big 21.9% of the time against 0.4% for every other
# turn: 53 misses, 9.2M tokens, 12% of all cache writes (2026-10-13). The
# fingerprint now leaves deferred tools out, as Anthropic's key does; a change
# to any tool the prompt renders still starts a new lineage. RAISES cache reads,
# tokens saved unchanged in aggregate, so check cache_read per request with
# savings:did after the stable ships.
# Exact-pin gated to wheel 0.41.0; self-neutralizes when the wheel's
# fingerprint already ignores a deferred tool. Kill switch:
# HEADROOM_DEFERRED_TOOL_AFFINITY=0.
_hd_dta_flag = _hd_os.environ.get("HEADROOM_DEFERRED_TOOL_AFFINITY", "1")
if _hd_os.environ.get("HEADROOM_SDK") == "headroom-desktop-proxy" and (
    _hd_dta_flag.strip().lower() not in ("", "0", "false", "no", "off")
):
    try:
        import importlib.metadata as _hd_dta_meta

        if _hd_dta_meta.version("headroom-ai") == "0.41.0":
            from headroom.cache import prefix_tracker as _hd_dta_pt

            _hd_dta_orig = _hd_dta_pt.segment_fingerprint

            def _hd_dta_fingerprint(value):
                if isinstance(value, dict) and isinstance(value.get("tools"), list):
                    value = {
                        **value,
                        "tools": [
                            t
                            for t in value["tools"]
                            if not (isinstance(t, dict) and t.get("defer_loading"))
                        ],
                    }
                return _hd_dta_orig(value)

            _hd_dta_tool = {"name": "Read", "input_schema": {"type": "object"}}
            _hd_dta_deferred = {"name": "x", "defer_loading": True, "input_schema": {}}
            if _hd_dta_orig({"tools": [_hd_dta_tool]}) != _hd_dta_orig(
                {"tools": [_hd_dta_tool, _hd_dta_deferred]}
            ):
                # The handler imports the name at call time, so the module
                # attribute is the one it reads.
                _hd_dta_pt.segment_fingerprint = _hd_dta_fingerprint
                _hd_bound.add("deferred_tool_affinity")
    except Exception:
        # Fail-open to the wheel's fingerprint.
        pass

# --- Stream: a client that hangs up after the terminal event (#4286) ----------
# The direct HTTP SSE loop yields each upstream chunk to the client BEFORE it
# parses it. Codex closes the connection as soon as it reads
# response.completed, so the generator is closed at that yield: the terminal
# event and the usage in the same chunk are never parsed, completed_normally
# stays False, and since #3747 (0.40.0) the turn finalizes as a 502.
# emit_request_outcome drops a 502 whole (no /stats request, no savings, no
# PERF line) and the finalizer skips the prefix tracker, so the next turn of
# that conversation starts at frozen=0. 0.9.45-rc.12 recorded 0 of 8 Codex
# requests in the train's guest where 0.39.0 recorded 3 of 3 (2026-10-20).
# Upstream PR #4286 (open) parses each chunk before yielding it and records a
# hang-up after the client was handed the terminal event as completed; a
# hang-up before it stays a 502. Its _stream_response_inner hunks are applied
# VERBATIM to the installed method's source and compiled in the module's own
# globals; each must match its expected count or nothing binds. Its Bedrock
# and LiteLLM-backend hunks are left out: the desktop runs neither. Bookkeeping
# only, the bytes the client gets are unchanged; but Codex turns now update the
# prefix tracker, so check BOTH tok_saved/tok_before and cache_read/forwarded
# for Codex with savings:did after the stable ships.
# Exact-pin gated to wheel 0.41.0; self-neutralizes when the method already
# tracks client_left_after_terminal. Kill switch:
# HEADROOM_STREAM_HANGUP_AFTER_TERMINAL=0.
_HD_STH_HUNKS = (
    (
        '''        completed_normally = False
        pending_messages: list[dict] = []
''',
        '''        completed_normally = False
        # Set when the client hangs up after the terminal event; it marks
        # the outcome only, so pending messages are not drained into a
        # stream nobody reads.
        client_left_after_terminal = False
        # A terminal event the client was handed, not just one parsed from
        # upstream: the memory filter holds message_stop until the end.
        client_got_terminal = False
        pending_messages: list[dict] = []
''',
        1,
    ),
    (
        '''            else None
        )

        try:
            async with contextlib.aclosing(upstream_response) as response:
''',
        '''            else None
        )

        def _client_frame(frame: bytes) -> bytes:
            """``_guard_client_bytes``, noting when the terminal event goes out."""
            nonlocal client_got_terminal
            guarded = _guard_client_bytes(frame)
            if guarded and not client_got_terminal:
                if memory_filter is None:
                    # Unfiltered, the client gets each whole chunk once it
                    # is parsed, so every event the parser has seen.
                    client_got_terminal = stream_state["stream_terminal"]
                else:
                    # Filtered frames are complete events the filter decoded.
                    client_got_terminal = any(
                        _sse_event_outcome(name, data, stream_state["sse_dialect"])[1]
                        for name, data in parse_sse_events_from_byte_buffer(bytearray(frame))
                    )
            return guarded

        try:
            async with contextlib.aclosing(upstream_response) as response:
''',
        1,
    ),
    (
        '''                    # Always stream immediately \u2014 buffering breaks
                    # real-time clients (LangGraph, LangChain, etc.)
                    # The context guard runs last, on exactly what the
                    # client receives (after the memory filter), and may
                    # hold back bytes only until the first complete event.
                    client_frames = (
                        [chunk] if memory_filter is None else memory_filter.feed(chunk)
                    )
                    for frame in client_frames:
                        guarded_frame = _guard_client_bytes(frame)
                        if guarded_frame:
                            yield guarded_frame

''',
        "",
        1,
    ),
    (
        '''                    # Parse complete SSE events from buffer
                    usage = self._parse_sse_usage_from_buffer(stream_state, provider)
''',
        '''                    # Parse complete SSE events from buffer. A failure (e.g.
                    # invalid UTF-8) is raised once the chunk is forwarded:
                    # malformed upstream content still reaches the client.
                    parse_error: Exception | None = None
                    try:
                        usage = self._parse_sse_usage_from_buffer(stream_state, provider)
                    except Exception as e:
                        usage, parse_error = None, e
''',
        1,
    ),
    (
        '''                                "cache_creation_ephemeral_1h_input_tokens"
                            ]

            # Memory tool handling after stream completes
''',
        '''                                "cache_creation_ephemeral_1h_input_tokens"
                            ]

                    # Always stream immediately \u2014 buffering breaks
                    # real-time clients (LangGraph, LangChain, etc.)
                    # The context guard runs last, on exactly what the
                    # client receives (after the memory filter), and may
                    # hold back bytes only until the first complete event.
                    # Yielded only after the chunk is parsed: a client may
                    # hang up on the terminal event (Codex does), closing
                    # this generator at the yield.
                    client_frames = (
                        [chunk] if memory_filter is None else memory_filter.feed(chunk)
                    )
                    for frame in client_frames:
                        guarded_frame = _client_frame(frame)
                        if guarded_frame:
                            yield guarded_frame
                    if parse_error is not None:
                        raise parse_error

            # Memory tool handling after stream completes
''',
        1,
    ),
    # The memory filter's closing and continuation frames.
    ("guarded_frame = _guard_client_bytes(frame)", "guarded_frame = _client_frame(frame)", 3),
    (
        '''        except (httpx.ConnectError, httpx.ConnectTimeout, httpx.PoolTimeout) as e:
''',
        '''        except (GeneratorExit, asyncio.CancelledError):
            # Codex closes the connection as soon as it reads
            # response.completed, before the upstream EOF ends the loop.
            client_left_after_terminal = (
                client_got_terminal and not stream_state["stream_failed"]
            )
            raise
        except (httpx.ConnectError, httpx.ConnectTimeout, httpx.PoolTimeout) as e:
''',
        1,
    ),
    (
        '''                    upstream_response.status_code, completed_normally
                ),
''',
        '''                    upstream_response.status_code,
                    completed_normally or client_left_after_terminal,
                ),
''',
        1,
    ),
)
_hd_sth_flag = _hd_os.environ.get("HEADROOM_STREAM_HANGUP_AFTER_TERMINAL", "1")
if _hd_os.environ.get("HEADROOM_SDK") == "headroom-desktop-proxy" and (
    _hd_sth_flag.strip().lower() not in ("", "0", "false", "no", "off")
):
    try:
        import importlib.metadata as _hd_sth_meta

        if _hd_sth_meta.version("headroom-ai") == "0.41.0":
            import __future__ as _hd_sth_future
            import inspect as _hd_sth_inspect
            import textwrap as _hd_sth_textwrap

            from headroom.proxy import helpers as _hd_sth_helpers
            from headroom.proxy.handlers import streaming as _hd_sth_mod

            _hd_sth_src = _hd_sth_textwrap.dedent(
                _hd_sth_inspect.getsource(_hd_sth_mod.StreamingMixin._stream_response_inner)
            )
            if "client_left_after_terminal" not in _hd_sth_src:
                for _hd_sth_old, _hd_sth_new, _hd_sth_n in _HD_STH_HUNKS:
                    if _hd_sth_src.count(_hd_sth_old) != _hd_sth_n:
                        raise LookupError(_hd_sth_old.strip().splitlines()[0])
                    _hd_sth_src = _hd_sth_src.replace(_hd_sth_old, _hd_sth_new)
                _hd_sth_ns = {}
                # streaming.py defers annotations; the recompiled method must too.
                exec(
                    compile(
                        _hd_sth_src,
                        "<headroom-desktop: upstream #4286 _stream_response_inner>",
                        "exec",
                        flags=_hd_sth_future.annotations.compiler_flag,
                        dont_inherit=True,
                    ),
                    vars(_hd_sth_mod),
                    _hd_sth_ns,
                )
                # The PR imports it at module level; the method reads it as a global.
                _hd_sth_mod.parse_sse_events_from_byte_buffer = (
                    _hd_sth_helpers.parse_sse_events_from_byte_buffer
                )
                _hd_sth_fn = _hd_sth_ns["_stream_response_inner"]
                _hd_sth_fn.__qualname__ = "StreamingMixin._stream_response_inner"
                _hd_sth_mod.StreamingMixin._stream_response_inner = _hd_sth_fn
                _hd_bound.add("stream_hangup_after_terminal")
    except Exception:
        # Fail-open to the wheel's stream loop.
        pass

# --- Event-loop stall dump (desktop diagnostic, RUST-86) ----------------------
# /stats on the backend port times out after 15s while /readyz answers right
# after, on idle hosts as often as busy ones: something holds the event loop
# and is gone before anything outside the process can look (the watchdog's
# SIGUSR1 dump only runs on a wedge, and never on Windows). A 1s heartbeat on
# the serving loop keeps re-arming faulthandler's timer; a loop stalled for
# HEADROOM_LOOP_STALL_DUMP seconds misses the re-arm and faulthandler's own C
# thread writes every Python thread's stack to logs/loop-stall.txt. Armed after
# startup (the lifespan boot blocks the loop by design), disarmed on shutdown.
# The desktop attaches the loop thread's stack to the next RUST-86 event.
# OFF BY DEFAULT (0), opt-in for one machine at a time: that dump reads other
# threads' frames without the GIL, and on 2026-10-05 it segfaulted a backend
# whose Kompress warm-up thread was inside torch, and in a scratch repro spun
# forever in dump_frame while the next re-arm (cancel_dump_traceback_later,
# GIL held) waited on it, wedging the process. A stall is when other threads
# are busy, so the fleet's ~45 RUST-86 stalls a day would each risk that.
# A safe form samples sys._current_frames() from a Python thread holding the
# GIL. Diagnostic only: nothing the proxy forwards changes.
if _hd_os.environ.get("HEADROOM_SDK") == "headroom-desktop-proxy" and _hd_sys.argv[:1] != ["-c"]:
    try:
        _hd_ls_secs = float(_hd_os.environ.get("HEADROOM_LOOP_STALL_DUMP", "0"))
        if _hd_ls_secs > 0:
            import headroom.paths as _hd_ls_paths
            import uvicorn.server as _hd_ls_uv

            _hd_ls_orig_startup = _hd_ls_uv.Server.startup
            _hd_ls_orig_shutdown = _hd_ls_uv.Server.shutdown
            _hd_ls_armed = [False]

            async def _hd_ls_startup(self, *args, **kwargs):
                result = await _hd_ls_orig_startup(self, *args, **kwargs)
                if self.should_exit:
                    return result
                try:
                    import asyncio as _hd_ls_asyncio

                    loop = _hd_ls_asyncio.get_running_loop()
                    path = _hd_ls_paths.log_dir() / "loop-stall.txt"
                    path.parent.mkdir(parents=True, exist_ok=True)
                    # O_BINARY: a Windows text-mode fd would turn each "\n"
                    # into "\r\n" and blur the blank line between threads.
                    fd = _hd_os.open(
                        str(path),
                        _hd_os.O_WRONLY
                        | _hd_os.O_CREAT
                        | _hd_os.O_TRUNC
                        | getattr(_hd_os, "O_BINARY", 0),
                        0o600,
                    )
                    _hd_ls_armed[0] = True

                    def beat():
                        if not _hd_ls_armed[0]:
                            return
                        # One dump is a few KB; the cap only bites on a loop
                        # that stalls every few seconds for hours.
                        if _hd_os.lseek(fd, 0, _hd_os.SEEK_CUR) > 262144:
                            _hd_os.ftruncate(fd, 0)
                            _hd_os.lseek(fd, 0, _hd_os.SEEK_SET)
                        faulthandler.dump_traceback_later(_hd_ls_secs, file=fd)
                        loop.call_later(1.0, beat)

                    beat()
                except Exception:
                    pass
                return result

            async def _hd_ls_shutdown(self, *args, **kwargs):
                _hd_ls_armed[0] = False
                faulthandler.cancel_dump_traceback_later()
                return await _hd_ls_orig_shutdown(self, *args, **kwargs)

            _hd_ls_uv.Server.startup = _hd_ls_startup
            _hd_ls_uv.Server.shutdown = _hd_ls_shutdown
            _hd_bound.add("loop_stall_dump")
    except Exception:
        pass

# --- Forget half-imported packages (RUST-S8) -----------------------------------
# Every vendor above swallows its own failure. When the import it triggers dies
# partway (Application Control blocking `_overlapped.pyd` inside asyncio),
# Python drops the package but keeps the submodules that loaded, so the proxy's
# own `import asyncio` then dies on "NameError: name 'base_events' is not
# defined": a corrupt-stdlib signature to the desktop, which discarded and
# re-downloaded a sound interpreter. Dropping every module whose parent is gone
# makes that import raise the real error. A no-op on a healthy boot.
try:
    _hd_orphans = True
    while _hd_orphans:
        _hd_orphans = [
            k for k in _hd_sys.modules if "." in k and k.rpartition(".")[0] not in _hd_sys.modules
        ]
        for _hd_k in _hd_orphans:
            del _hd_sys.modules[_hd_k]
except Exception:
    pass

# --- One INFO line: which vendors bound (observability) -----------------------
# Without it nobody can tell on a user machine whether a vendor (say
# HEADROOM_TOOL_REF_HINT) is active. Names only, no user data. Written to
# stderr (the proxy log) because logging is not configured yet at import
# time. Proxy process only: the learn subprocess and other venv Pythons do not
# set HEADROOM_SDK, and the proxy's own multiprocessing spawn children
# (image isolation) inherit it but start with `-c`.
_HD_VENDORS = (
    "user_turn_verbatim",
    "savings_fold_guard",
    "cache_integrity",
    "prefix_replay_guard",
    "cc_switch_reset",
    "tool_ref_hint",
    "message_window",
    "embed_batch_cap",
    "maturation_floor",
    "proxied_guarded_upstreams",
    "output_warmup",
    "learn_rule_coerce",
    "learn_prior_local",
    "learn_block_cap",
    "learn_drop_error_recovery",
    "learn_codex_retries",
    "learn_stderr_squeeze",
    "learn_stdin_early_exit",
    "learn_loop_budget",
    "learn_opencode_v2",
    "web_search_history",
    "buffered_upstream_stream",
    "deferred_tool_affinity",
    "stream_hangup_after_terminal",
    "loop_stall_dump",
    "startup_stall_dump",
)
if _hd_os.environ.get("HEADROOM_SDK") == "headroom-desktop-proxy" and _hd_sys.argv[:1] != ["-c"]:
    try:
        _hd_sys.stderr.write(
            "INFO:headroom.desktop:sitecustomize vendors bound=%s skipped=%s\n"
            % (
                ",".join(n for n in _HD_VENDORS if n in _hd_bound) or "-",
                ",".join(n for n in _HD_VENDORS if n not in _hd_bound) or "-",
            )
        )
        _hd_sys.stderr.flush()
    except Exception:
        pass

"#;
/// Default-on passthrough for the rollout registry's `read_maturation` feature.
///
/// Requested for every install since 0.9.7-rc.1 (2026-09-02): the 0.37.0
/// freeze policy caps tail-only compression at ~1-2% on big sessions, and
/// read_maturation is the cache-safe recovery leg (holds Read results out of
/// the provider cache until they quiesce; never mutates a cached byte). Since
/// 0.9.34-rc.5 the tail over a held Read is cached instead (the
/// `held_read_breakpoint` vendor, native as #3977 since the 0.41.0 wheel); from rc.10 a Read the cached prefix has passed stays verbatim,
/// since maturing it would rewrite every cached byte after it. It is
/// still cache-breakpoint machinery -- the class that cost 89 installs ~17pp
/// on 0.9.4 -- so the falsey spellings of `HEADROOM_READ_MATURATION` stay a
/// no-rebuild kill switch, and the rc does not promote to stable until
/// `bin/rails savings:did` has judged a full staging day on BOTH tok_saved
/// AND cache_read.
fn read_maturation_env() -> Vec<(String, String)> {
    read_maturation_env_from(std::env::var("HEADROOM_READ_MATURATION").ok().as_deref())
}

fn read_maturation_env_from(raw: Option<&str>) -> Vec<(String, String)> {
    // Absent means on; an explicit value still passes through verbatim.
    let value = raw.map_or("1", str::trim);
    // Mirror the wheel's own truthiness so "0"/"false"/"off" mean off rather
    // than "the variable is present, therefore on".
    if matches!(
        value.to_ascii_lowercase().as_str(),
        "" | "0" | "false" | "no" | "off"
    ) {
        return Vec::new();
    }
    vec![("HEADROOM_READ_MATURATION".to_string(), value.to_string())]
}

/// Pre-upstream concurrency passed to the backend: 2x logical cores,
/// clamped to [8, 64]. See the spawn-site comment for why the proxy's own
/// 8-cap is safe to exceed under the desktop's env. An explicit
/// `HEADROOM_ANTHROPIC_PRE_UPSTREAM_CONCURRENCY` in the environment wins, so a
/// power user with 30+ concurrent sessions can raise it without a rebuild.
fn pre_upstream_concurrency() -> usize {
    if let Some(n) = std::env::var("HEADROOM_ANTHROPIC_PRE_UPSTREAM_CONCURRENCY")
        .ok()
        .and_then(|v| v.parse::<usize>().ok())
        .filter(|n| *n > 0)
    {
        return n;
    }
    let cores = std::thread::available_parallelism().map_or(4, |n| n.get());
    (cores * 2).clamp(8, 64)
}

/// `default` for an engine switch the desktop sets, unless the user exported
/// `name` themselves (launchctl setenv, a Windows user variable, the shell
/// that starts the Linux app): a non-empty value passes through for the wheel
/// to parse. `HEADROOM_DEDUPE=0` plus `HEADROOM_COLD_RECOMPACT=0` turns the
/// cross-turn "same as msg M" pointer off without a rebuild; both are needed,
/// because cold-prefix recompaction builds its own router with dedupe forced on.
fn user_env_or(name: &str, default: &str) -> String {
    std::env::var(name)
        .ok()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| default.to_string())
}

/// Interval estimate of OpenAI's prompt-cache TTL from the backend's
/// `cache_ttl_observations.jsonl` (written under HEADROOM_CACHE_TTL_LEARN):
/// hit idles bound the TTL from below (cache proven alive), `ttl_expiry` miss
/// idles bound it from above (cache proven dead). Returns the smallest
/// observed death-idle beyond the largest observed life-idle, so an estimation
/// error can only skip a recompaction, never bust a warm cache; None when the
/// bounds overlap or samples are thin (< 3 hits or < 3 expiry misses).
/// Mirrors the upstream `headroom-cache-ttl` estimator (headroom PR #2670);
/// delete once a wheel ships it and a scheduled run replaces this.
fn learned_openai_ttl_seconds(obs_path: &Path) -> Option<u64> {
    let data = std::fs::read_to_string(obs_path).ok()?;
    let mut hit_idles: Vec<f64> = Vec::new();
    let mut expiry_idles: Vec<f64> = Vec::new();
    for line in data.lines() {
        let Ok(row) = serde_json::from_str::<serde_json::Value>(line) else {
            continue;
        };
        if row.get("provider").and_then(|v| v.as_str()) != Some("openai") {
            continue;
        }
        let idle = row
            .get("idle_seconds")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.0);
        if idle <= 0.0 {
            continue;
        }
        if row.get("is_miss").and_then(|v| v.as_bool()) == Some(true) {
            if row.get("reason").and_then(|v| v.as_str()) == Some("ttl_expiry") {
                expiry_idles.push(idle);
            }
        } else {
            hit_idles.push(idle);
        }
    }
    if hit_idles.len() < 3 || expiry_idles.len() < 3 {
        return None;
    }
    let max_hit_idle = hit_idles.into_iter().fold(0.0f64, f64::max);
    let learned = expiry_idles
        .into_iter()
        .filter(|&idle| idle > max_hit_idle)
        .fold(f64::INFINITY, f64::min);
    if !learned.is_finite() {
        return None;
    }
    Some((learned as u64).clamp(300, 3600))
}

fn parse_major_minor_patch(s: &str) -> Option<(u32, u32, u32)> {
    let head = s.split(['-', '+']).next()?;
    let mut parts = head.split('.');
    let major: u32 = parts.next()?.parse().ok()?;
    let minor: u32 = parts.next()?.parse().ok()?;
    let patch: u32 = parts.next().and_then(|p| p.parse().ok()).unwrap_or(0);
    Some((major, minor, patch))
}

/// True when the previously-installed receipt is too old to safely apply an
/// in-place pip upgrade against — caller should fall through to the atomic
/// venv rebuild path. Unparseable versions are treated as too old (be
/// conservative: a rebuild is always safe, an unsafe in-place is not).
fn receipt_requires_atomic_rebuild(previous_version: &str) -> bool {
    match parse_major_minor_patch(previous_version) {
        Some(v) => v < ATOMIC_REBUILD_FLOOR_VERSION,
        None => true,
    }
}
