    #[test]
    fn sitecustomize_unfolds_tool_schema_dollars() {
        // 0.36.0's attribution unification folds priced tool-schema dollars
        // into compression_savings_usd while every token field beside it
        // stays message-only, inflating any $/token read on the persisted
        // state by 1 + tool/message (5.59x measured; an implied $32.88/M next
        // to models listing at $10/M). #3170 (0.40.0) added a disjoint field
        // but kept the fold. The guard zeroes the tool_schema bucket before
        // the fold so the desktop's lifetime dollars keep their 0.35.0
        // meaning. Behaviour is proven by
        // savings_fold_guard_behaves_against_the_installed_wheel.
        let py = super::SITECUSTOMIZE_PY;
        assert!(py.contains("HEADROOM_SAVINGS_FOLD_GUARD"));
        assert!(py.contains("_hd_sf_st.SavingsTracker.record_request = _hd_sf_record"));
        // The unfold works on a copy -- the caller's mapping is not mutated.
        assert!(py.contains("unfolded = dict(priced)"));
        assert!(py.contains(r#"unfolded["tool_schema"] = 0.0"#));
        // Gated on the fold itself, not on #3170's disjoint field, which
        // shipped beside the fold and stood the guard down while it summed.
        assert!(py.contains(r#""compression_usd + tool_schema_usd" in _hd_sf_inspect.getsource("#));
        assert!(!py.contains("_empty_display_session()"));
        // Only the dollar fold is undone; the token side must pass through.
        assert!(!py.contains(r#"kwargs["tool_search_saved"]"#));
        // The 0.37.0 wheel handles Codex additional_tools natively (#3186 +
        // #3194), so the desktop lift is gone with the pin bump.
        assert!(!py.contains("HEADROOM_ADDITIONAL_TOOLS_GUARD"));
        assert!(!py.contains("additional_tools"));
    }

    /// The fold guard against the installed wheel: a priced request with $1 of
    /// compression and $5 of tool-schema savings adds $1 to the persisted
    /// compression dollars, and $6 (the fold) with the kill switch. 0.41.0
    /// still folds, while its disjoint field stood the old gate down.
    #[test]
    fn savings_fold_guard_behaves_against_the_installed_wheel() {
        let python =
            ManagedRuntime::bootstrap_root(&crate::storage::app_data_dir()).managed_python();
        if !python.exists() || !installed_wheel_is_pinned(&python) {
            eprintln!("skipping: no managed runtime on the {HEADROOM_PINNED_VERSION} pin");
            return;
        }
        let dir = tempfile::tempdir().expect("tempdir");
        std::fs::write(dir.path().join("sitecustomize.py"), super::SITECUSTOMIZE_PY).unwrap();
        // Each run persists to a fresh dir under the temp dir, nowhere else.
        let probe = r#"
import os, sys, tempfile
from headroom.proxy import savings_tracker as st
t = st.SavingsTracker(path=os.path.join(tempfile.mkdtemp(dir=sys.argv[1]), "savings.json"))
priced = {"compression": 1.0, "tool_schema": 5.0, "compression_list": 1.0,
          "tool_schema_list": 5.0, "provider_cache": 0.0, "output_shaping": 0.0,
          "basis": st.BASIS_LIST}
before = dict(priced)
t.record_request(model="claude-sonnet-4-5", input_tokens=10000, tokens_saved=1000,
                 tool_search_saved=5000, estimated_savings_usd=priced)
assert priced == before, "caller's mapping mutated"
print(round(t.snapshot()["lifetime"]["compression_savings_usd"], 6))
"#;
        let run = |flag: &str| {
            let out = crate::proc::command(&python)
                .args(["-c", probe])
                .arg(dir.path())
                .env("PYTHONPATH", dir.path())
                .env("HEADROOM_SDK", "headroom-desktop-proxy")
                .env("HEADROOM_SAVINGS_FOLD_GUARD", flag)
                .env("LITELLM_LOCAL_MODEL_COST_MAP", "True")
                .output()
                .expect("run savings fold probe");
            (
                String::from_utf8_lossy(&out.stdout).trim().to_string(),
                String::from_utf8_lossy(&out.stderr).to_string(),
            )
        };
        let (on, on_err) = run("1");
        assert_eq!(on, "1.0", "stderr:\n{on_err}");
        let (off, off_err) = run("0");
        assert_eq!(off, "6.0", "stderr:\n{off_err}");
    }

    #[test]
    fn sitecustomize_ports_prefix_replay_guard() {
        // Upstream issue #3379: the 0.36.x non-inflation bound declines the
        // cached-prefix replay exactly when background compression shrinks
        // already-forwarded history, busting the provider prompt cache every
        // time kompress lands. The guard stubs the sizing helper per call so
        // the bound never fires, and goes inert once a wheel ships the
        // enforce_non_inflation parameter.
        let py = super::SITECUSTOMIZE_PY;
        assert!(py.contains("HEADROOM_PREFIX_REPLAY_GUARD"));
        assert!(py.contains("upstream issue #3379"));
        // Gated on the fix's parameter being ABSENT under either name the
        // upstream PR shipped (v1 flag, reworked floor), so a fixed wheel
        // keeps its own replay policy.
        assert!(py.contains("in _hd_pr_pt.overlay_cached_prefix.__code__.co_varnames"));
        assert!(py.contains(r#""enforce_non_inflation", "confirmed_frozen_count""#));
        // Two-pass probe: bound-on first (a shrinking repair is accepted
        // as-is), then stubbed sizing so the replay always wins -- v0.35.0's
        // policy, which has no bound at all. The floor-limited variant
        // shipped in 0.9.4 measured WORSE than no guard (fleet cache
        // coverage 1.20 -> 0.94) because bytes past the floor still bust, so
        // there must be no partial splice here.
        assert!(py.contains("if r1 is not optimized:"));
        assert!(py.contains(r#"_hd_pr_pt._compact_json_bytes = lambda value: b"""#));
        assert!(py.contains("_hd_pr_pt._compact_json_bytes = _hd_pr_saved"));
        assert!(py.contains("_hd_pr_pt.overlay_cached_prefix = _hd_pr_overlay"));
        assert!(
            !py.contains("_hd_pr_floors"),
            "floor splice must not come back"
        );
        assert!(
            !py.contains("r2[:floor]"),
            "partial replay leaves busts past the floor"
        );
    }

    #[test]
    fn sitecustomize_vendors_tool_ref_hint() {
        // The residual tool_reference 400 gets a "start a new session" hint.
        // Behaviour is proven by tool_ref_hint_behaves_against_the_installed_wheel;
        // this pins the shape.
        let py = super::SITECUSTOMIZE_PY;
        assert!(py.contains("HEADROOM_TOOL_REF_HINT"));
        assert!(py.contains(r#"_hd_hint_meta.version("headroom-ai") == "0.41.0""#));
        // Wraps the buffered-error seam and post-processes its Response.
        assert!(py.contains("_hd_hint_mod.StreamingMixin._stream_response = _hd_hint_wrapped"));
        assert!(py.contains("def _hd_hint_apply(result):"));
        // Assert the load-bearing marker the idempotency guard keys on, not the
        // user-facing copy (which is free to change without breaking this test).
        assert!(py.contains(r#"b"Headroom:" not in body"#));
    }

    /// Vendor names the summary line reports: every `_hd_bound.add("x")` and
    /// the `_HD_VENDORS` tuple must name the same set, or a vendor drops out
    /// of the line.
    fn sitecustomize_vendor_names(py: &str) -> (Vec<String>, Vec<String>) {
        let added = py
            .split("_hd_bound.add(\"")
            .skip(1)
            .map(|rest| rest.split('"').next().unwrap().to_string())
            .collect();
        let tuple = py
            .split("_HD_VENDORS = (")
            .nth(1)
            .and_then(|rest| rest.split(')').next())
            .expect("_HD_VENDORS tuple");
        let listed = tuple
            .split('"')
            .skip(1)
            .step_by(2)
            .map(str::to_string)
            .collect();
        (added, listed)
    }

    #[test]
    fn sitecustomize_logs_which_vendors_bound() {
        // Nobody could tell on a user machine whether a vendor (say
        // HEADROOM_TOOL_REF_HINT) was active. One line per proxy process,
        // names only; the -c gate keeps the proxy's multiprocessing spawn
        // children (image isolation) and ad-hoc probes quiet.
        let py = super::SITECUSTOMIZE_PY;
        let (mut added, mut listed) = sitecustomize_vendor_names(py);
        assert!(added.len() >= 15, "bind markers missing: {added:?}");
        added.sort();
        added.dedup();
        listed.sort();
        assert_eq!(added, listed, "_hd_bound.add names != _HD_VENDORS");
        let tail = &py[py.find("_HD_VENDORS = (").unwrap()..];
        assert!(tail.contains(r#"_hd_os.environ.get("HEADROOM_SDK") == "headroom-desktop-proxy""#));
        assert!(tail.contains(r#"_hd_sys.argv[:1] != ["-c"]"#));
        assert!(tail.contains("INFO:headroom.desktop:sitecustomize vendors bound="));
    }

    /// RUST-86: a stalled backend loop must leave its stack where the
    /// `/stats` timeout report can pick it up. Real uvicorn server, real
    /// faulthandler timer, a 2.5s block of the serving loop.
    #[test]
    fn loop_stall_dump_behaves_against_the_installed_wheel() {
        let python =
            ManagedRuntime::bootstrap_root(&crate::storage::app_data_dir()).managed_python();
        if !python.exists() || !installed_wheel_is_pinned(&python) {
            eprintln!("skipping: no managed runtime on the {HEADROOM_PINNED_VERSION} pin");
            return;
        }
        let dir = tempfile::tempdir().expect("tempdir");
        std::fs::write(dir.path().join("sitecustomize.py"), super::SITECUSTOMIZE_PY).unwrap();
        let probe = dir.path().join("probe.py");
        std::fs::write(
            &probe,
            r#"import asyncio, time, uvicorn

async def app(scope, receive, send):
    while scope["type"] == "lifespan":
        message = await receive()
        if message["type"] == "lifespan.startup":
            await send({"type": "lifespan.startup.complete"})
        else:
            await send({"type": "lifespan.shutdown.complete"})
            return

def hd_probe_blocks_the_loop():
    time.sleep(2.5)

async def main():
    server = uvicorn.Server(uvicorn.Config(app, host="127.0.0.1", port=0, log_level="error"))
    serving = asyncio.create_task(server.serve())
    while not server.started:
        await asyncio.sleep(0.05)
    await asyncio.sleep(1.5)
    hd_probe_blocks_the_loop()
    server.should_exit = True
    await serving

asyncio.run(main())
"#,
        )
        .unwrap();
        let workspace = dir.path().join("workspace");
        let out = crate::proc::command(&python)
            .arg(&probe)
            .env("PYTHONPATH", dir.path())
            .env("HEADROOM_SDK", "headroom-desktop-proxy")
            .env("HEADROOM_WORKSPACE_DIR", &workspace)
            .env("HEADROOM_LOOP_STALL_DUMP", "1")
            .env("LITELLM_LOCAL_MODEL_COST_MAP", "True")
            .output()
            .expect("run probe");
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(out.status.success(), "{stderr}");
        assert!(stderr.contains("loop_stall_dump"), "{stderr}");
        let (_, stacks) = crate::state::recent_loop_stall(
            &workspace.join("logs").join("loop-stall.txt"),
            std::time::SystemTime::now(),
        )
        .expect("a stalled loop leaves a dump");
        let main = stacks.split("\n\n").next().unwrap();
        assert!(main.contains("hd_probe_blocks_the_loop"), "{stacks}");
    }

    /// RUST-P1: a backend that never binds leaves every thread's stack in
    /// the desktop's file; one whose uvicorn startup returns (port bound)
    /// leaves nothing, however long it runs after that.
    #[test]
    fn startup_stall_dump_behaves_against_the_installed_wheel() {
        let python =
            ManagedRuntime::bootstrap_root(&crate::storage::app_data_dir()).managed_python();
        if !python.exists() || !installed_wheel_is_pinned(&python) {
            eprintln!("skipping: no managed runtime on the {HEADROOM_PINNED_VERSION} pin");
            return;
        }
        let dir = tempfile::tempdir().expect("tempdir");
        std::fs::write(dir.path().join("sitecustomize.py"), super::SITECUSTOMIZE_PY).unwrap();
        // os._exit: the desktop kills a backend that never bound, and a normal
        // interpreter exit waits on a dump that spun (see the vendor). The
        // timer is armed before the vendors' imports, and a dump that lands
        // mid-import can kill the probe outright (no stderr at all, CI on
        // 2026-10-09 at 1s), so it fires well after them, in the sleep.
        let wedged = dir.path().join("wedged.py");
        std::fs::write(
            &wedged,
            "import os, time\n\ndef hd_probe_never_binds():\n    time.sleep(30)\n\n\
             hd_probe_never_binds()\nos._exit(0)\n",
        )
        .unwrap();
        // The vendor's own timer is armed at interpreter start, before the
        // vendors' imports (a few seconds), so the bound probe re-arms a short
        // one on the same file: startup returning must cancel whichever is set.
        let bound = dir.path().join("bound.py");
        std::fs::write(
            &bound,
            r#"import asyncio, faulthandler, os, sys, time, uvicorn

async def app(scope, receive, send):
    while scope["type"] == "lifespan":
        message = await receive()
        if message["type"] == "lifespan.startup":
            await send({"type": "lifespan.startup.complete"})
        else:
            await send({"type": "lifespan.shutdown.complete"})
            return

async def main():
    # A child Python must not inherit the proxy's timer.
    assert "HEADROOM_STARTUP_STALL_DUMP" not in os.environ
    fd = os.open(sys.argv[1], os.O_WRONLY | os.O_APPEND)
    # Long enough that a loaded machine binds first (3s flaked in a full
    # suite at load ~45); the sleep below outlasts it, so a missed cancel dumps.
    faulthandler.dump_traceback_later(10.0, file=fd)
    server = uvicorn.Server(uvicorn.Config(app, host="127.0.0.1", port=0, log_level="error"))
    serving = asyncio.create_task(server.serve())
    while not server.started:
        await asyncio.sleep(0.05)
    time.sleep(11.0)
    server.should_exit = True
    await serving

asyncio.run(main())
"#,
        )
        .unwrap();
        let spawn = |name: &str, probe: &std::path::Path, secs: &str| {
            let dump = dir.path().join(format!("{name}-stall.txt"));
            let stderr = dir.path().join(format!("{name}-stderr.txt"));
            let child = crate::proc::command(&python)
                .arg(probe)
                .arg(&dump)
                .env("PYTHONPATH", dir.path())
                .env("HEADROOM_SDK", "headroom-desktop-proxy")
                .env("HEADROOM_STARTUP_STALL_DUMP", &dump)
                .env("HEADROOM_STARTUP_STALL_DUMP_SECS", secs)
                .env("LITELLM_LOCAL_MODEL_COST_MAP", "True")
                .stdout(std::process::Stdio::null())
                .stderr(std::fs::File::create(&stderr).unwrap())
                .spawn()
                .expect("run probe");
            (child, dump, stderr)
        };
        let runs = [
            spawn("wedged", &wedged, "15"),
            spawn("bound", &bound, "600"),
        ];
        let started = std::time::Instant::now();
        for (mut child, _, stderr_path) in runs {
            let status = loop {
                if let Some(status) = child.try_wait().expect("probe wait") {
                    break status;
                }
                if started.elapsed() > Duration::from_secs(180) {
                    let _ = child.kill();
                    panic!(
                        "probe hung: {}",
                        std::fs::read_to_string(&stderr_path).unwrap()
                    );
                }
                std::thread::sleep(Duration::from_millis(100));
            };
            let stderr = std::fs::read_to_string(&stderr_path).unwrap();
            assert!(status.success(), "{stderr}");
            let bound_vendors = stderr
                .lines()
                .find_map(|l| l.strip_prefix("INFO:headroom.desktop:sitecustomize vendors bound="))
                .and_then(|l| l.split_once(" skipped="))
                .map(|(bound, _)| bound.split(',').any(|v| v == "startup_stall_dump"));
            assert_eq!(bound_vendors, Some(true), "{stderr}");
        }
        let dump = std::fs::read_to_string(dir.path().join("wedged-stall.txt")).unwrap();
        assert!(dump.starts_with("Timeout (0:00:15)!"), "{dump}");
        // The main thread is in the probe's sleep by now; on a machine loaded
        // enough to still be importing, the frame walk may stop short. It
        // still names a frame.
        let stacks = crate::state::stall_dump_stacks(&dump).expect("parsable dump");
        let main = stacks.split("\n\n").next().unwrap();
        assert!(
            main.starts_with("Thread 0x") && main.contains("  File \""),
            "{stacks}"
        );
        assert_eq!(
            std::fs::read_to_string(dir.path().join("bound-stall.txt")).unwrap(),
            ""
        );
    }

    #[test]
    fn sitecustomize_vendor_summary_behaves_against_the_installed_wheel() {
        let python =
            ManagedRuntime::bootstrap_root(&crate::storage::app_data_dir()).managed_python();
        if !python.exists() || !installed_wheel_is_pinned(&python) {
            eprintln!("skipping: no managed runtime on the {HEADROOM_PINNED_VERSION} pin");
            return;
        }
        let dir = tempfile::tempdir().expect("tempdir");
        std::fs::write(dir.path().join("sitecustomize.py"), super::SITECUSTOMIZE_PY).unwrap();
        let probe = dir.path().join("probe.py");
        std::fs::write(&probe, "pass\n").unwrap();
        let run = |args: &[&std::ffi::OsStr], sdk: &str, hint: &str| {
            let out = crate::proc::command(&python)
                .args(args)
                .env("PYTHONPATH", dir.path())
                .env("HEADROOM_SDK", sdk)
                .env("HEADROOM_TOOL_REF_HINT", hint)
                .env("LITELLM_LOCAL_MODEL_COST_MAP", "True")
                .output()
                .expect("run probe");
            String::from_utf8_lossy(&out.stderr)
                .lines()
                .filter(|l| l.starts_with("INFO:headroom.desktop:sitecustomize vendors"))
                .map(str::to_owned)
                .collect::<Vec<_>>()
        };
        let proxy = run(&[probe.as_os_str()], "headroom-desktop-proxy", "1");
        assert_eq!(proxy.len(), 1, "{proxy:?}");
        let (bound, skipped) = proxy[0].split_once(" skipped=").unwrap();
        assert!(bound.contains("tool_ref_hint"), "{}", proxy[0]);
        assert!(!skipped.contains("tool_ref_hint"), "{}", proxy[0]);
        // Opt-in only: its all-threads dump can crash or wedge a busy backend.
        assert!(skipped.contains("loop_stall_dump"), "{}", proxy[0]);
        // Windows spawns only: unix takes its stacks with SIGABRT.
        assert!(skipped.contains("startup_stall_dump"), "{}", proxy[0]);
        let off = run(&[probe.as_os_str()], "headroom-desktop-proxy", "0");
        assert!(
            off.len() == 1
                && off[0]
                    .split_once(" skipped=")
                    .unwrap()
                    .1
                    .contains("tool_ref_hint"),
            "{off:?}"
        );
        // Not the learn subprocess or any other venv Python, not `-c` children.
        assert!(run(&[probe.as_os_str()], "", "1").is_empty());
        assert!(run(
            &["-c".as_ref(), "pass".as_ref()],
            "headroom-desktop-proxy",
            "1"
        )
        .is_empty());
    }

    /// RUST-S8: the vendors swallowed an import that died inside asyncio, and
    /// the submodules it left behind turned the proxy's own `import asyncio`
    /// into a NameError the desktop read as a corrupt base stdlib.
    #[test]
    fn blocked_asyncio_raises_its_own_error_against_the_installed_wheel() {
        let python =
            ManagedRuntime::bootstrap_root(&crate::storage::app_data_dir()).managed_python();
        if !python.exists() || !installed_wheel_is_pinned(&python) {
            eprintln!("skipping: no managed runtime on the {HEADROOM_PINNED_VERSION} pin");
            return;
        }
        let dir = tempfile::tempdir().expect("tempdir");
        std::fs::write(dir.path().join("hd_site.py"), super::SITECUSTOMIZE_PY).unwrap();
        // Application Control's block is in place before any vendor runs.
        std::fs::write(
            dir.path().join("sitecustomize.py"),
            r#"import os, sys
class _Block:
    def find_spec(self, name, path=None, target=None):
        if name in ("asyncio.unix_events", "asyncio.windows_events"):
            raise ImportError("DLL load failed while importing _overlapped: blocked")
sys.meta_path.insert(0, _Block())
_p = os.path.join(os.path.dirname(__file__), "hd_site.py")
with open(_p, encoding="utf-8") as _f:
    exec(compile(_f.read(), _p, "exec"))
"#,
        )
        .unwrap();
        let probe = dir.path().join("probe.py");
        std::fs::write(
            &probe,
            "try:\n    import asyncio\nexcept Exception as e:\n    print(type(e).__name__, e)\n",
        )
        .unwrap();
        let out = crate::proc::command(&python)
            .arg(&probe)
            .env("PYTHONPATH", dir.path())
            .env("HEADROOM_SDK", "headroom-desktop-proxy")
            .env("LITELLM_LOCAL_MODEL_COST_MAP", "True")
            .output()
            .expect("run probe");
        let stdout = String::from_utf8_lossy(&out.stdout);
        let stderr = String::from_utf8_lossy(&out.stderr);
        // The vendors did hit the block, or this proves nothing.
        assert!(
            stderr
                .split_once(" skipped=")
                .is_some_and(|(_, skipped)| skipped.contains("message_window")),
            "{stderr}"
        );
        assert!(
            stdout.contains("ImportError DLL load failed while importing _overlapped"),
            "{stdout}\n{stderr}"
        );
    }

