    /// Every addon keeps its card on every platform; the ones with no artifact
    /// for this target carry a reason instead (codebase-memory ships no Windows
    /// binary, rtk none for windows-aarch64). A card without an artifact and
    /// without a reason would offer an Install button that only ever errors.
    #[test]
    fn addons_without_an_artifact_for_this_target_carry_a_reason() {
        let (_root, _runtime, manager) = seed_test_runtime("manifest-artifacts");
        let tools = manager.list_tools();
        let reason_for = |id: &str| {
            tools
                .iter()
                .find(|tool| tool.id == id)
                .unwrap_or_else(|| panic!("{id} card must exist on every platform"))
                .unavailable_reason
                .clone()
        };

        assert_eq!(
            reason_for("rtk").is_none(),
            rtk_distribution_artifact().is_ok(),
            "rtk is installable exactly when its artifact resolves"
        );
        assert_eq!(
            reason_for("codebase-memory").is_none(),
            codebase_memory_distribution_artifact().is_ok(),
            "codebase-memory is installable exactly when its artifact resolves"
        );
        // Nothing platform-gated about the Python addons: never gray them.
        assert!(reason_for("markitdown").is_none());
        assert!(reason_for("serena").is_none());
    }

    #[test]
    fn unavailable_reason_names_the_platform_and_the_reason() {
        // The message is user-facing copy on a grayed card, so it has to say
        // both which platform is missing and why, without a bare target triple.
        let Some(reason) = addon_unavailable_reason("codebase-memory") else {
            return; // this target has a build; nothing to phrase
        };
        assert!(reason.starts_with("Not available on "), "{reason}");
        assert!(reason.contains("codebase-memory"), "{reason}");
    }

    fn listed_tool(manager: &ToolManager, id: &str) -> ManagedTool {
        manager
            .list_tools()
            .into_iter()
            .find(|tool| tool.id == id)
            .expect("tool in manifest")
    }

    #[test]
    fn list_tools_reports_the_installed_version_and_offers_the_pinned_one() {
        let (_root, runtime, manager) = seed_test_runtime("addon-update");

        // Not installed: the card shows what an install would give you.
        let absent = listed_tool(&manager, "markitdown");
        assert_eq!(absent.version, MARKITDOWN_PINNED_VERSION);
        assert!(!absent.update_available);
        assert!(absent.available_version.is_none());

        let entrypoint = manager.markitdown_entrypoint();
        fs::create_dir_all(entrypoint.parent().expect("bin parent")).expect("bin dir");
        fs::write(&entrypoint, b"#!/bin/sh\n").expect("entrypoint");
        fs::write(
            runtime.tools_dir.join("markitdown.json"),
            br#"{"version":"0.1.5","enabled":true}"#,
        )
        .expect("receipt");

        // Installed and behind: report what is on disk, offer the pin.
        let stale = listed_tool(&manager, "markitdown");
        assert_eq!(stale.version, "0.1.5");
        assert!(stale.update_available);
        assert_eq!(
            stale.available_version.as_deref(),
            Some(MARKITDOWN_PINNED_VERSION)
        );

        fs::write(
            runtime.tools_dir.join("markitdown.json"),
            format!(r#"{{"version":"{MARKITDOWN_PINNED_VERSION}","enabled":true}}"#).as_bytes(),
        )
        .expect("receipt");
        let current = listed_tool(&manager, "markitdown");
        assert_eq!(current.version, MARKITDOWN_PINNED_VERSION);
        assert!(!current.update_available);

        // The pin is a minimum: someone ahead of it is current, not overdue.
        // Prompting here would be an offer to downgrade.
        fs::write(
            runtime.tools_dir.join("markitdown.json"),
            br#"{"version":"99.0.0","enabled":true}"#,
        )
        .expect("receipt");
        let ahead = listed_tool(&manager, "markitdown");
        assert_eq!(ahead.version, "99.0.0");
        assert!(!ahead.update_available);

        // An unreadable version is treated as current for the same reason.
        fs::write(
            runtime.tools_dir.join("markitdown.json"),
            br#"{"version":"main","enabled":true}"#,
        )
        .expect("receipt");
        assert!(!listed_tool(&manager, "markitdown").update_available);

        // Disabled and behind: no Update button. Every installer writes
        // `enabled: true`, so updating here would switch the addon back on
        // behind the user's back.
        fs::write(
            runtime.tools_dir.join("markitdown.json"),
            br#"{"version":"0.1.5","enabled":false}"#,
        )
        .expect("receipt");
        let disabled = listed_tool(&manager, "markitdown");
        assert_eq!(disabled.version, "0.1.5");
        assert!(!disabled.update_available);

        // A receipt whose payload is gone is not an install: no version claim,
        // no update prompt.
        fs::remove_file(&entrypoint).expect("remove entrypoint");
        let orphaned = listed_tool(&manager, "markitdown");
        assert_eq!(orphaned.version, MARKITDOWN_PINNED_VERSION);
        assert!(!orphaned.update_available);
    }

    #[test]
    fn pip_runs_load_the_ipv6_fallback_hook_from_beside_their_venv() {
        let (_root, runtime, _manager) = seed_test_runtime("pip-net-hook");
        let python = runtime.managed_python();
        let pythonpath = |args: &[&str]| {
            build_command(&python, args, &runtime.root_dir)
                .get_envs()
                .find(|(key, _)| *key == "PYTHONPATH")
                .and_then(|(_, value)| value.map(PathBuf::from))
        };

        let hook = pythonpath(&["-m", "pip", "install", "x"]).expect("pip gets the hook");
        let venv = python.parent().and_then(Path::parent).expect("venv dir");
        assert_eq!(hook, venv.with_file_name("pip-net-hook"));
        assert_eq!(
            fs::read_to_string(hook.join("sitecustomize.py")).expect("hook written"),
            super::PIP_NET_SITECUSTOMIZE
        );
        // Everything else keeps PYTHONPATH stripped (the proxy, smoke tests).
        assert_eq!(pythonpath(&["-c", "import headroom"]), None);
    }

    #[test]
    fn serena_on_an_intel_mac_pins_the_release_whose_cryptography_installs_there() {
        // RUST-F6: serena-agent 1.7.0 pins cryptography==50.0.0, which has no
        // x86_64 macOS wheel, so every Intel Mac install tried a Rust build
        // and failed. 1.6.1 pins 48.0.1, the last universal2 build.
        assert_eq!(super::serena_pinned_version(true), "1.6.1");
        // The runtime lock holds Intel Macs on 48.0.1 for the same reason. If
        // that pin moves, cryptography may ship an Intel wheel again: check
        // whether the Serena pin's cryptography does, and drop the Intel
        // branch if so.
        assert!(
            HEADROOM_REQUIREMENTS_LOCK.contains(
                "cryptography==48.0.1; platform_machine == \"x86_64\" and sys_platform == \"darwin\""
            ),
            "the lock's Intel Mac cryptography pin moved; re-check serena_pinned_version"
        );
    }

    #[test]
    fn serena_without_bundled_uvx_offers_an_update_that_reinstalls_it() {
        let (_root, runtime, manager) = seed_test_runtime("serena-uvx");
        let entrypoint = manager.serena_entrypoint();
        fs::create_dir_all(entrypoint.parent().expect("bin parent")).expect("bin dir");
        fs::write(&entrypoint, b"#!/bin/sh\n").expect("entrypoint");
        fs::write(
            runtime.tools_dir.join("serena.json"),
            format!(r#"{{"version":"{SERENA_PINNED_VERSION}","enabled":true}}"#).as_bytes(),
        )
        .expect("receipt");

        // At the pin but installed before uv was bundled: Python symbol tools
        // are broken, so offer a plain "Update" (no version to move to).
        let legacy = listed_tool(&manager, "serena");
        assert!(legacy.update_available);
        assert!(legacy.available_version.is_none());

        fs::write(manager.serena_uvx(), b"#!/bin/sh\n").expect("uvx");
        assert!(!listed_tool(&manager, "serena").update_available);
    }

    fn retired_leftovers(parent: &Path) -> usize {
        fs::read_dir(parent)
            .expect("read parent")
            .flatten()
            .filter(|e| {
                e.file_name()
                    .to_string_lossy()
                    .starts_with("serena-venv.old-")
            })
            .count()
    }

    #[test]
    fn retiring_a_venv_frees_its_path_and_clears_earlier_leftovers() {
        let dir = tempfile::tempdir().expect("tempdir");
        let venv = dir.path().join("serena-venv");
        fs::create_dir_all(venv.join("bin")).expect("venv");
        fs::write(venv.join("bin").join("serena"), b"x").expect("entrypoint");
        // One a running server held through an earlier update.
        fs::create_dir_all(dir.path().join("serena-venv.old-1").join("bin")).expect("leftover");

        super::retire_venv(&venv).expect("retire");
        assert!(!venv.exists());
        assert_eq!(retired_leftovers(dir.path()), 0);
        super::retire_venv(&venv).expect("nothing to retire is fine");
    }

    #[cfg(windows)]
    #[test]
    fn retiring_a_venv_a_running_server_holds_frees_its_path_at_once() {
        let dir = tempfile::tempdir().expect("tempdir");
        let venv = dir.path().join("serena-venv");
        fs::create_dir_all(venv.join("Scripts")).expect("venv");
        // Stand-in for serena's MCP server: an executable running out of the venv.
        let exe = venv.join("Scripts").join("ping.exe");
        fs::copy(r"C:\Windows\System32\PING.EXE", &exe).expect("copy ping");
        let mut server = crate::proc::command(&exe)
            .args(["-n", "60", "127.0.0.1"])
            .stdout(std::process::Stdio::null())
            .spawn()
            .expect("spawn");
        let retired = super::retire_venv(&venv);
        let freed = !venv.exists();
        server.kill().expect("kill");
        server.wait().expect("wait");
        retired.expect("a running server does not stop the move aside");
        assert!(freed, "the venv path is free while the server runs");

        // The next install retries whatever the server held.
        super::retire_venv(&venv).expect("retire again");
        assert_eq!(retired_leftovers(dir.path()), 0);
    }

    #[test]
    fn pending_addon_update_treats_the_pin_as_a_minimum() {
        assert_eq!(
            pending_addon_update("serena", Some("1.6.1"), "1.7.0").as_deref(),
            Some("1.7.0")
        );
        assert_eq!(pending_addon_update("serena", Some("1.7.0"), "1.7.0"), None);
        // Ahead of the pin: current, not overdue. Never offer a downgrade.
        assert_eq!(pending_addon_update("serena", Some("1.8.0"), "1.7.0"), None);
        assert_eq!(pending_addon_update("serena", Some("2.0.0"), "1.7.0"), None);
        assert_eq!(pending_addon_update("serena", None, "1.7.0"), None);
        assert_eq!(
            pending_addon_update("serena", Some("nightly"), "1.7.0"),
            None
        );

        // Plugins are pinned to the newest plugin.json on GitHub: offered only
        // when that is ahead of the install, never before the first fetch.
        assert_eq!(
            pending_addon_update("ponytail", Some("4.9.0"), "5.2.0").as_deref(),
            Some("5.2.0")
        );
        assert_eq!(
            pending_addon_update("ponytail", Some("5.2.0"), "5.2.0"),
            None
        );
        assert_eq!(pending_addon_update("ponytail", Some("4.9.0"), ""), None);
        assert_eq!(
            pending_addon_update("chisle", Some("4.9.0"), PLUGIN_DISPLAY_VERSION),
            None
        );
        assert_eq!(pending_addon_update("caveman", None, "4.0.1"), None);

        // Self-maintaining: rtk is refreshed at launch, headroom rides the
        // runtime upgrade. Neither gets an Update button, stale or not.
        assert_eq!(
            pending_addon_update("rtk", Some("0.1.0"), RTK_VERSION),
            None
        );
        assert_eq!(
            pending_addon_update("headroom", Some("0.1.0"), HEADROOM_PINNED_VERSION),
            None
        );
    }

