        super::write_headroom_to_claude_json_at(&path, Path::new("/bin/headroom"), "http://p")
            .unwrap();

        let after: serde_json::Value = serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
        assert_eq!(after["oauthAccount"]["id"], "abc");
