    #[test]
    fn sharing_violation_path_reads_the_file_pip_names() {
        let stderr = "WARNING: Ignoring invalid distribution ~eadroom-ai\n\
            ERROR: Could not install packages due to an OSError: [WinError 32] O processo \
            não pode acessar o arquivo: 'c:\\\\users\\\\o\\\\venv\\\\scripts\\\\headroom.exe'\n\
            Check the permissions.\n";
        assert_eq!(
            super::sharing_violation_path(stderr).as_deref(),
            Some(r"c:\users\o\venv\scripts\headroom.exe")
        );
        // An apostrophe in the path makes Python quote it with double quotes.
        assert_eq!(
            super::sharing_violation_path(r#"[WinError 32] in use: "c:\\users\\o'brien\\x.dll""#)
                .as_deref(),
            Some(r"c:\users\o'brien\x.dll")
        );
        // A failed rename names both ends; the held file is the source, not
        // the `.deleteme` pip never got to create (RUST-29 on 0.9.2x).
        assert_eq!(
            super::sharing_violation_path(
                r"ERROR: Could not install packages due to an OSError: [WinError 32] in use: 'c:\\v\\scripts\\headroom.exe' -> 'c:\\v\\scripts\\headroom.exe.deleteme'"
            )
            .as_deref(),
            Some(r"c:\v\scripts\headroom.exe")
        );
        assert_eq!(
            super::sharing_violation_path("[WinError 5] Access is denied"),
            None
        );
    }

    /// A sharing violation is antivirus holding a freshly written wheel; the
    /// old 2s+5s schedule burned all its attempts before the scan finished
    /// (RUST-6Z). Everything else keeps the original three attempts.
    #[test]
    fn pip_retry_backoff_gives_sharing_violations_more_room() {
        use super::pip_retry_backoff as backoff;
        let plain = "exit=1; stderr tail: ERROR: No matching distribution found";
        assert_eq!(backoff(1, plain), Some(Duration::from_secs(2)));
        assert_eq!(backoff(2, plain), Some(Duration::from_secs(5)));
        assert_eq!(backoff(3, plain), None, "third failure is final");

        // Localized stderr: only the code identifies it.
        let locked = "ERROR: Could not install packages due to an OSError: [WinError 32] \
                      O arquivo já está sendo usado por outro processo: 'C:\\x\\torch.dll'";
        assert_eq!(backoff(3, locked), Some(Duration::from_secs(10)));
        assert_eq!(backoff(5, locked), Some(Duration::from_secs(30)));
        assert_eq!(backoff(6, locked), None);
        // Rust-side io error shape.
        assert!(super::pip_failure_is_sharing_violation(
            "renaming x: (os error 32)"
        ));
        // 320-329 are different errors.
        assert!(!super::pip_failure_is_sharing_violation(
            "[WinError 3] path not found"
        ));
        assert!(!super::pip_failure_is_sharing_violation(
            "[WinError 320] whatever"
        ));
        assert_eq!(backoff(0, locked), None, "attempt numbering starts at 1");
        // RUST-6S: the stash-rename fallback under a live holder.
        assert!(super::pip_failure_is_sharing_violation(
            "OSError: [WinError 183] Eine Datei kann nicht erstellt werden, wenn sie bereits \
             vorhanden ist: 'C:\\\\x\\\\venv\\\\Lib\\\\site-packages\\\\~~adroom'"
        ));
        assert!(!super::pip_failure_is_sharing_violation(
            "[WinError 183] exists: 'C:\\\\x\\\\file.txt'"
        ));
    }

    #[test]
    fn every_index_resolving_pip_install_is_wheels_only() {
        // A dependency built from source needs a compiler the user was never
        // asked to have, and fails minutes later with a clang/cargo error they
        // cannot act on. `PIP_ONLY_BINARY` prevents that -- but only on the
        // call sites that carry it, and these arg lists are copy-pasted across
        // nine of them. Any install that resolves from an index must be
        // wheels-only; the optional markitdown/serena addons deliberately do
        // not resolve from `--extra-index-url` and so are not covered here.
        let source = include_str!("tool_manager.rs");
        let indexed = source.matches("\"--extra-index-url\",").count();
        // Split so this needle does not count itself in the scan above.
        let only_binary = source.matches(concat!("PIP_ONLY_", "BINARY,")).count();
        assert!(indexed > 0, "sanity: expected index-resolving installs");
        assert_eq!(
            indexed, only_binary,
            "an index-resolving pip install is missing PIP_ONLY_BINARY \
             ({indexed} indexed installs vs {only_binary} wheels-only)"
        );
    }

    #[test]
    fn pip_failure_category_splits_the_buckets_triage_uses() {
        // One issue per cause class, not per stderr tail (RUST-6M/6N/6P) and
        // not one flat grab-bag (RUST-5Q).
        let cases = [
            ("exit=1; stderr tail: No module named pip", "no-pip"),
            (
                "exit=1; stderr tail: FileNotFoundError: [Errno 2] No usable temporary directory",
                "no-tempdir",
            ),
            (
                "exit=1; stderr tail: OSError: [Errno 28] No space left on device",
                "disk-full",
            ),
            ("exit=1; stderr tail: Check the permissions.", "permission"),
            // RUST-6S on 0.9.47-rc.7, verbatim: the long path pushed "Check
            // the permissions." past the tail, and the event filed `other`.
            (
                "exit=1; stderr tail: ERROR: Could not install packages due to an OSError: \
                 [WinError 32] The process cannot access the file because it is being used by \
                 another process: '~\\\\AppData\\\\Local\\\\Headroom\\\\headroom\\\\runtime\\\\venv\
                 \\\\Scripts\\\\headroom.exe' -> '~\\\\AppData\\\\Local\\\\Headroom\\\\headroom\\\\runt",
                "file-in-use",
            ),
            (
                "exit=1; stderr tail: ERROR: Could not find a version that satisfies the \
                 requirement onnxruntime==1.27.0 (from versions: 1.23.2)\nERROR: No matching \
                 distribution found for onnxruntime==1.27.0",
                "no-matching-dist",
            ),
            (
                "exit=1; stderr tail: ERROR: Could not install packages due to an OSError: \
                 [Errno 2] No such file or directory: 'C:\\\\...\\\\INSTALLERvp0i8uew.tmp'",
                "missing-file",
            ),
            (
                "exit=1; stderr tail: ERROR: Failed building wheel for hnswlib",
                "build",
            ),
            (
                "exit=1; stderr tail: Could not fetch URL https://pypi.org/simple/",
                "network",
            ),
            ("exit=1; stderr tail: something new", "other"),
            // Hash-checking mode (#125's hashed locks), pip's verbatim heads:
            // a swapped or corrupted wheel, a pin added without its hash, an
            // unpinned requirement. Never the "other" grab-bag.
            (
                "exit=1; stderr tail: ERROR: THESE PACKAGES DO NOT MATCH THE HASHES FROM THE \
                 REQUIREMENTS FILE. If you have updated the package versions, please update \
                 the hashes. Otherwise, examine the package contents carefully; someone may \
                 have tampered with them.\n    pydantic-core==2.46.4 from https://x/a.whl:\n\
                 Expected sha256 aa\n             Got        bb",
                "hash-mismatch",
            ),
            (
                "exit=1; stderr tail: ERROR: Hashes are required in --require-hashes mode, but \
                 they are missing from some requirements. Here is a list of those requirements \
                 along with the hashes their downloaded archives actually had.",
                "hash-mismatch",
            ),
            (
                "exit=1; stderr tail: ERROR: In --require-hashes mode, all requirements must \
                 have their versions pinned with ==. These do not:\n    anyio>=4",
                "hash-mismatch",
            ),
            // RUST-6S third shape: venv damaged in place, launcher stub can't
            // resolve the interpreter, pip never runs.
            ("exit=106; stderr tail: No pyvenv.cfg file", "venv-broken"),
            // RUST-29/RUST-JF, verbatim tails: pip's own import died.
            (
                "exit=1; stderr tail: ImportError: cannot import name 'CacheControlAdapter' \
                 from 'pip._vendor.cachecontrol' (unknown location)",
                "pip-broken",
            ),
            (
                "exit=1; stderr tail: ModuleNotFoundError: No module named 'pip._internal.cli'",
                "pip-broken",
            ),
            // RUST-8K, verbatim: Windows access-denied on a Korean install.
            // Only the numeric code survives translation.
            (
                "publishing extracted python into ~\\AppData\\Local\\Headroom: \
                 액세스가 거부되었습니다. (os error 5)",
                "permission",
            ),
            // RUST-8K again, second cause under the same title: the bundled
            // interpreter's OpenSSL dies inside `ensurepip`, before pip runs.
            (
                "installing pip into the Headroom-managed virtualenv: command failed (exit 1): \
                 python.exe -m ensurepip --upgrade --default-pip\nstderr:\n\
                 OPENSSL_Uplink(00007FF926407C58,08): no OPENSSL_Applink",
                "openssl-applink",
            ),
            // RUST-8K, third cause: Windows Application Control blocked the
            // venv python before it could run. Localized prose, so the
            // numeric code carries the match.
            (
                "creating Headroom-managed virtualenv: starting python.exe -m venv: \
                 An Application Control policy has blocked this file. (os error 4551)",
                "app-control",
            ),
            // RUST-8K, fourth cause: same machine on retry -- python ran,
            // but _ssl's DLLs stayed blocked, so ensurepip dies importing
            // pip and only this ImportError survives.
            (
                "installing pip into the Headroom-managed virtualenv: command failed (exit 1): \
                 python.exe -m ensurepip --upgrade --default-pip\nstderr:\n\
                 ImportError: cannot import name 'HTTPSHandler' from 'urllib.request'",
                "ssl-missing",
            ),
            // RUST-6S on 0.9.48, verbatim: the base lost `linecache.py`.
            (
                "exit=1; stderr tail:     import sys, os, time, io, re, traceback, warnings, \
                 weakref, collections.abc\n  File \"~\\AppData\\Local\\Headroom\\headroom\\\
                 runtime\\python\\Lib\\traceback.py\", line 5, in <module>\n    \
                 import linecache\nModuleNotFoundError: No module named 'linecache'",
                "base-stdlib-broken",
            ),
            // The macOS network errnos must not read as a denial: the
            // closing paren in the needle is what keeps 51 out of "permission".
            (
                "exit=1; stderr tail: error sending request (os error 51)",
                "other",
            ),
        ];
        for (compact, expected) in cases {
            assert_eq!(pip_failure_category(compact), expected, "for: {compact}");
        }
    }

    #[test]
    fn plugin_registration_says_unknown_when_the_registry_is_unreadable() {
        // RUST-DQ: an absent registry used to read as "not installed", so a CLI
        // that exited 0 was reported as a failed install. Only a registry we can
        // actually read may say no.
        let tmp = tempfile::tempdir().expect("temp home");
        let _home = HomeGuard::new(tmp.path());
        let plugin = plugin_addon("ponytail").expect("ponytail addon");

        assert_eq!(PluginHost::ClaudeCode.plugin_registration(plugin), None);
        assert_eq!(PluginHost::Codex.plugin_registration(plugin), None);

        let claude = tmp.path().join(".claude").join("plugins");
        fs::create_dir_all(&claude).unwrap();
        let registry = claude.join("installed_plugins.json");
        fs::write(&registry, br#"{"version":2,"plugins":{}}"#).unwrap();
        assert_eq!(
            PluginHost::ClaudeCode.plugin_registration(plugin),
            Some(false)
        );
        fs::write(
            &registry,
            format!(
                r#"{{"version":2,"plugins":{{"{}":[{{"scope":"user"}}]}}}}"#,
                plugin.plugin_ref
            ),
        )
        .unwrap();
        assert_eq!(
            PluginHost::ClaudeCode.plugin_registration(plugin),
            Some(true)
        );

        let codex = tmp.path().join(".codex");
        fs::create_dir_all(&codex).unwrap();
        let config = codex.join("config.toml");
        fs::write(&config, "model = \"gpt-5\"\n").unwrap();
        assert_eq!(PluginHost::Codex.plugin_registration(plugin), Some(false));
        fs::write(
            &config,
            format!("[plugins.\"{}\"]\nenabled = true\n", plugin.plugin_ref),
        )
        .unwrap();
        assert_eq!(PluginHost::Codex.plugin_registration(plugin), Some(true));
    }

    #[test]
    fn codex_list_line_installed_reads_the_status_column() {
        // Rows as codex-cli 0.153.0 prints them.
        let r = "ponytail@ponytail";
        assert!(codex_list_line_installed(
            "  ponytail@ponytail   installed, enabled   4.10.0   https://github.com/DietrichGebert/ponytail.git",
            r
        ));
        assert!(codex_list_line_installed(
            "ponytail@ponytail installed, disabled 4.10.0",
            r
        ));
        assert!(!codex_list_line_installed(
            "ponytail@ponytail not installed 4.10.0",
            r
        ));
        assert!(!codex_list_line_installed(
            "engineering-suite-ponytail@openai-curated-remote installed, enabled",
            r
        ));
        assert!(!codex_list_line_installed(
            "PLUGIN STATUS VERSION SOURCE",
            r
        ));
    }

    /// Offline at a login launch, the version fetch must come back within the
    /// retry on every platform. Backdating the round's start could not reach
    /// before boot on Windows, so there it waited out the full 6-hour TTL.
    #[test]
    fn a_failed_plugin_version_round_is_due_again_within_the_retry() {
        use std::time::Instant;
        let cache: super::PluginLatestCache = std::sync::Arc::new(parking_lot::Mutex::new(Some((
            Instant::now() + super::PLUGIN_LATEST_TTL,
            Default::default(),
        ))));
        super::plugin_latest_round_failed(&cache);
        let due = cache.lock().as_ref().unwrap().0;
        assert!(due <= Instant::now() + super::PLUGIN_LATEST_RETRY);
    }

    #[test]
    fn codex_plugin_disabled_reads_the_plugins_enabled_flag() {
        let plugin = super::plugin_addon("chisle").unwrap();
        let config = |body: &str| format!("[plugins.\"{}\"]\n{body}\n", plugin.plugin_ref);
        assert!(super::codex_plugin_disabled_in(
            &config("enabled = false"),
            plugin
        ));
        assert!(!super::codex_plugin_disabled_in(
            &config("enabled = true"),
            plugin
        ));
        assert!(!super::codex_plugin_disabled_in(&config(""), plugin));
        assert!(!super::codex_plugin_disabled_in("not = [toml", plugin));
    }

    #[test]
    fn codex_cached_plugin_version_takes_the_newest_version_dir() {
        let cache = tempfile::tempdir().unwrap();
        let plugin = super::plugin_addon("ponytail").unwrap();
        assert_eq!(codex_cached_plugin_version(cache.path(), plugin), None);
        let dir = cache.path().join("ponytail").join("ponytail");
        for name in ["4.9.0", "5.10.0", "latest"] {
            std::fs::create_dir_all(dir.join(name)).unwrap();
        }
        assert_eq!(
            codex_cached_plugin_version(cache.path(), plugin).as_deref(),
            Some("5.10.0")
        );
    }

    #[test]
    fn missing_plugin_prereqs_names_every_missing_one_at_once() {
        assert_eq!(
            MissingPluginPrereqs(vec!["node"]).to_string(),
            NO_NODE_FOR_PLUGIN
        );
        let all = MissingPluginPrereqs(vec!["cli", "node", "git"]).to_string();
        assert!(
            all.starts_with(
                "This addon needs the Claude Code or Codex CLI, Node.js (https://nodejs.org) and Git ("
            ),
            "{all}"
        );
        assert!(all.ends_with("restart Headroom and try again."), "{all}");
    }

